class SF_Calc 
{
    public static function calculateWin($pers1, $pers2, $attackType)
    {
        global $db, $SSID;
        $logs = [];
        
        $qry = $db->prepare("SELECT * FROM items WHERE owner_id = (SELECT user_data.user_id FROM user_data WHERE user_data.ssid = :ssid) AND slot = 2 LIMIT 1");
        $qry->bindParam(':ssid', $SSID);
        $qry->execute();
        
        $witch = $qry->fetchAll(PDO::FETCH_ASSOC);
        
        $enchant = $witch[0]['enchant'] ?? null; 

        if ($attackType === 'mobattack' && $enchant == 855638016) {
            $begin = true;
        } else {
            $begin = rand(0, 100) < 50;  
        }

        while ($pers1->getHP() > 0 && $pers2->getHP() > 0) {
            if (!$begin) {
                $log1 = [0, 0, 0];
            } else {
                $crit = $pers1->ifCrit($pers2->getLvl());
                $hit = self::getRandomDPS($pers1, $pers2, 0) * $crit * $pers2->getArmor($pers1);
                $log1 = $pers2->setHit($hit, $crit, $pers1);
            }

            if ((int)$pers2->getHP() <= 0) {
                $log2 = [0, 0, 0];
            } else {
                $crit = $pers2->ifCrit($pers1->getLvl());
                $hit = self::getRandomDPS($pers2, $pers1, 0) * $crit * $pers1->getArmor($pers2);
                $log2 = $pers1->setHit($hit, $crit, $pers2);
            }

            $log1[0] = $pers1->getHP();
            $log2[0] = $pers2->getHP();
            
            $logs[] = $log1;
            $logs[] = $log2;
            
            $begin = true;
        }

        return $logs;
    }

    private static function getRandomDPS($pers1, $pers2, $n)
    {
        $k = 1;
        
        $minDmg = (int)round($pers1->WeaponMin() * $k);
        $maxDmg = (int)round($pers1->WeaponMax() * $k);
        
        $dps = rand($minDmg, $maxDmg);
        
        return max(1, ceil($dps));
        
    }
}

class Char 
{
    protected int $str = 0;
    protected int $dex = 0;
    protected int $int = 0;
    protected int $wit = 0;
    protected int $luck = 0;
    protected int $armor = 0;
    protected int $class = 0;
    protected int $lvl = 0;
    protected int $hp = 0;
    protected int $uid = 0;
    protected ?stdClass $dmg = null;
    protected array $items = [];

    public function __construct($db_data)
    {
        global $db, $SSID, $character_data;

        $this->class = (int)($db_data['class'] ?? 0);
        $this->lvl   = (int)($db_data['lvl'] ?? 0);
        $this->uid   = (int)($db_data['user_id'] ?? 0);

        $portalLifeBonus   = ((int)($db_data['portal_monster'] ?? 0) + (((int)($db_data['portal_act'] ?? 1) - 1) * 10) - 1);
        $portalDamageBonus = ((int)($db_data['g_monster'] ?? 0) + (((int)($db_data['g_act'] ?? 1) - 1) * 10) - 1); 

        $qry = $db->prepare("SELECT * FROM items WHERE owner_id = (SELECT user_data.user_id FROM user_data WHERE user_data.ssid = :ssid) AND slot = 8 LIMIT 1");
        $qry->bindParam(':ssid', $SSID);
        $qry->execute();
        
        $witch = $qry->fetchAll(PDO::FETCH_ASSOC);
        $enchantdmg = $witch[0]['enchant'] ?? null; 
        
        $critBonus = ($enchantdmg == 184549376) ? 1.05 : 1;

        $this->str  = (int)($db_data['attr_str'] ?? 0);
        $this->dex  = (int)($db_data['attr_agi'] ?? 0);
        $this->int  = (int)($db_data['attr_int'] ?? 0);
        $this->luck = (int)($db_data['attr_luck'] ?? 0);
        $this->wit  = (int)($db_data['attr_wit'] ?? 0);

        $qry = $db->prepare("SELECT * FROM items WHERE owner_id = :id AND item_type <= 10 AND slot <= 9");
        $qry->bindParam(':id', $this->uid);
        $qry->execute();
        $this->items = $qry->fetchAll(PDO::FETCH_ASSOC);

        $itemStats = array_fill(0, 6, 0);
        
        $potionStat1 = $db_data['potion_value1'] ?? 0;
        $potionStat2 = $db_data['potion_value2'] ?? 0;
        $potionStat3 = $db_data['potion_value3'] ?? 0;

        foreach ($this->items as $item) {
            $itemStats[$item['atr_type_1'] ?? 0] += $item['atr_val_1'] ?? 0;
            $itemStats[$item['atr_type_2'] ?? 0] += $item['atr_val_2'] ?? 0;
            $itemStats[$item['atr_type_3'] ?? 0] += $item['atr_val_3'] ?? 0;
        }

        $this->str  += ($itemStats[1] ?? 0) + ($itemStats[6] ?? 0);
        $this->dex  += ($itemStats[2] ?? 0) + ($itemStats[6] ?? 0);
        $this->int  += ($itemStats[3] ?? 0) + ($itemStats[6] ?? 0);
        $this->wit  += ($itemStats[4] ?? 0) + ($itemStats[6] ?? 0);
        $this->luck += ($itemStats[5] ?? 0) + ($itemStats[6] ?? 0);

        for ($i = 1; $i < 4; $i++) {
            $potionId = $db_data['potion_id' . $i] ?? 0;
            switch ($potionId) {
                case 1:  $this->str  += round($this->str * 0.10); break;
                case 2:  $this->dex  += round($this->dex * 0.10); break;
                case 3:  $this->int  += round($this->int * 0.10); break;
                case 4:  $this->wit  += round($this->wit * 0.10); break;
                case 5:  $this->luck += round($this->luck * 0.10); break;
                case 6:  $this->str  += round($this->str * 0.15); break;
                case 7:  $this->dex  += round($this->dex * 0.15); break;
                case 8:  $this->int  += round($this->int * 0.15); break;
                case 9:  $this->wit  += round($this->wit * 0.15); break;
                case 10: $this->luck += round($this->luck * 0.25); break;
                case 11: $this->str  += round($this->str * 0.25); break;
                case 12: $this->dex  += round($this->dex * 0.25); break;
                case 13: $this->int  += round($this->int * 0.25); break;
                case 14: $this->wit  += round($this->wit * 0.25); break;
                case 15: $this->luck += round($this->luck * 0.25); break;
            }
        }

        $this->armor = $character_data[447] ?? 0; 
        
        $weapon = $this->getWeapon();
        $this->dmg = new stdClass();
        $this->dmg->min_damage = $weapon['dmg_min'] * (1 + $this->getPrimaryStatValue() / 10);
        $this->dmg->max_damage = $weapon['dmg_max'] * (1 + $this->getPrimaryStatValue() / 10) * $critBonus;
        
        $this->dmg->min_damage += ($portalDamageBonus / 100) * $this->dmg->min_damage;
        $this->dmg->max_damage += ($portalDamageBonus / 100) * $this->dmg->max_damage;

        switch ($this->class) {
            case 1: $k = 5; break;
            case 2: $k = 2; break;
            case 3: $k = 4; break;
            default: $k = 1; break;
        }

        $hpPotionVal = 0; 
        for ($i = 1; $i < 4; $i++) {
            if (($db_data['potion_id' . $i] ?? 0) == 16) {
                $hpPotionVal = round(($this->wit * $k * ($this->lvl + 1)) / 100 * 25);
            }
        }

        $this->hp = $this->wit * $k * ($this->lvl + 1) + $hpPotionVal;
        $this->hp += ($portalLifeBonus / 100) * $this->hp;
    }

    public function getPrimaryStatValue()
    {
        switch ($this->class) {
            case 1: return $this->str;
            case 2: return $this->int;
            case 3: return $this->dex;
            default: return 0;
        }
    }

    public function getClassName()
    {
        switch ($this->class) {
            case 1: return 'Warrior';
            case 2: return 'Mage';
            case 3: return 'Ranger';
            default: return 'Unknown';
        }
    }

    public function getClass()
    {
        switch ($this->class) {
            case 1: return 1;
            case 2: return 2;
            case 3: return 3;
            default: return 0;
        }
    }

    public function getHP()
    {
        return $this->hp;
    }

    public function setHP(int $hp2)
    {
        $this->hp = $hp2;
    }

    public function WeaponMin()
    {
        return $this->dmg->min_damage;
    }

    public function WeaponMax()
    {
        return $this->dmg->max_damage;
    }

    public function PrimaryAttr()
    {
        return $this->getPrimaryStatValue();
    }

    public function PrimaryAttrTitle()
    {
        switch ($this->class) {
            case 1: return "Str";
            case 2: return "Int";
            case 3: return "Dex";
            default: return "Str";
        }
    }

    public function getStr() { return $this->str; }
    public function getInt() { return $this->int; }
    public function getDex() { return $this->dex; }
    public function getWit() { return $this->wit; }
    public function getLuck() { return $this->luck; }

    public function ifCrit(int $oponent_lvl)
    {
        $rand = rand(0, 10000);
        $k = 1;
        $krit = $this->luck * 5 / ($oponent_lvl * 2);
        
        if ($krit > 50) {
            $krit = 50;
        }
        
        $krit *= 100;
        if ($rand < $krit) {
            $k = 2;
        }
        
        return $k;
    }

    public function setHit($hit, $crit, $op)
    {
        global $db; 

        $uid = $this->uid;
        $crit = ($crit == 2) ? 3 : 0;
        $slot = 9;

        $qrytms = $db->prepare("SELECT dmg_min FROM items WHERE owner_id = :id AND slot = :slot LIMIT 1");
        $qrytms->execute([':id' => $uid, ':slot' => $slot]);
        
        $protection = $qrytms->fetch(PDO::FETCH_ASSOC);
        $shield = $protection['dmg_min'] ?? 0;

        if ($shield == 0) { 
            $shield = 25;
        }

        if ($op->getClass() != 2) {
            if ($this->getClass() == 3) {
                if (rand(0, 100) > 50) {
                    $hit = 0;
                    $crit = 2;
                }
            } elseif ($this->getClass() == 1) {
                if (rand(0, 100) < $shield && $this->hasShield() != 0) {
                    $crit = 1;
                    $hit = 0;
                }
            }
        }

        $hit = (int)round($hit);

        $this->hp -= $hit; 
        return [0, $hit, $crit];
    }

    public function getLvl()
    {
        return $this->lvl;
    }

    public function getBlock($oponent)
    {
    }

    public function getArmor($oponent)
    {
        $armor = getRealArmor($this->uid) / $oponent->getLvl();
        
        if ($this->class == 1 && $armor > 50) $armor = 50;
        if ($this->class == 2 && $armor > 10) $armor = 10;
        if ($this->class == 3 && $armor > 25) $armor = 25;

        if ($oponent->getClass() == 2) {
            return 1;
        }
        
        return 1 - ($armor / 100);
    }

    public function getRes($oponent)
    {
        if ($this->class == $oponent->getClass()) {
            return 0;
        }
        
        $attr = "get" . $this->PrimaryAttrTitle();
        return $oponent->$attr() / 20;
    }

    public function getWeapon()
    {
        if (isset($this->items)) {
            foreach ($this->items as $item) {
                if ($item['slot'] == 8) {
                    return $item;
                }
            }
        }
        return $this->getDefaultItemTemplate();
    }

    public function getWeaponId()
    {
        $weap = $this->getWeapon();
        return (int)$weap['item_id'];
    }

    public function hasWeapon()
    {
        if (isset($this->items)) {
            foreach ($this->items as $item) {
                if ($item['slot'] == 8) return 1;
            }
        }
        return 0;
    }

    public function hasShield()
    {
        if (isset($this->items)) {
            foreach ($this->items as $item) {
                if ($item['slot'] == 9) return 2;
            }
        }
        return 0;
    }

    public function getShield()
    {
        if (isset($this->items)) {
            foreach ($this->items as $item) {
                if ($item['slot'] == 9) {
                    return $item;
                }
            }
        }
        return $this->getDefaultItemTemplate();
    }

    private function getDefaultItemTemplate()
    {
        return [
            "item_type"  => 0, "item_id"   => 0, "dmg_min"    => 1, "dmg_max"    => 2,
            "atr_type_1" => 0, "atr_type_2" => 0, "atr_type_3" => 0,
            "atr_val_1"  => 0, "atr_val_2"  => 0, "atr_val_3"  => 0,
            "gold"       => 0, "mush"       => 0
        ];
    }
}


class Monster extends Char 
{
    private $id;
    private $exp;
    private $silver;
    private $weapid;
    private $shilid; 

    public function __construct($lvl, $class, $str, $agi, $int, $wit, $luck, $dmg_min, $dmg_max, $hp, $armor, $id, $exp, $weapon_id, $shield_id = -1)
    {
        $this->class  = $class;
        $this->lvl    = $lvl;
        $this->id     = $id;
        $this->exp    = $exp;
        $this->silver = $exp * 2.5;
        $this->str    = $str;
        $this->dex    = $agi;
        $this->int    = $int;
        $this->luck   = $luck;
        $this->wit    = $wit;
        $this->armor  = $armor;
        
        $this->shilid = $shield_id;
        $this->weapid = $weapon_id;
        
        $this->dmg = new stdClass();
        $this->dmg->min_damage = $dmg_min;
        $this->dmg->max_damage = $dmg_max;
        $this->hp = $hp;
    }

    public function getId()
    {
        return $this->id;
    }

    public function getExp()
    {
        return $this->exp;
    }

    public function getGold()
    {
        return $this->silver;
    }

    public function getGoldTower()
    {
        return $this->exp;
    }

    public function hasWeapon()
    {
        return $this->weapid <= 0 ? $this->weapid : 1;
    }

    public function getWeaponId()
    {
        return $this->weapid;
    }

    public function getWeapon()
    {
        return [
            "item_type"  => 8,
            "item_id"    => $this->weapid,
            "dmg_min"    => 1,
            "dmg_max"    => 2,
            "atr_type_1" => 1,
            "atr_type_2" => 0,
            "atr_type_3" => 0,
            "atr_val_1"  => 1,
            "atr_val_2"  => 0,
            "atr_val_3"  => 0,
            "gold"       => 0,
            "mush"       => 0
        ];
    }

    public function hasShield()
    {
        if ($this->class == 1 && $this->shilid != -1) {
            return 2;
        }
        return 0;
    }

    public function getShield()
    {
        return [
            "item_type"  => 0,
            "item_id"    => $this->shilid,
            "dmg_min"    => 0,
            "dmg_max"    => 0,
            "atr_type_1" => 0,
            "atr_type_2" => 0,
            "atr_type_3" => 0,
            "atr_val_1"  => 0,
            "atr_val_2"  => 0,
            "atr_val_3"  => 0,
            "gold"       => 0,
            "mush"       => 0
        ];
    }
}

class Copycat extends Char 
{
    protected $id; 

    public function __construct($db_data)
    {
        global $db; 

        $this->class = $db_data['class'] ?? 0;
        $this->lvl   = $db_data['lvl'] ?? 0;
        $this->id    = $db_data['id'] ?? 0;
        
        $this->uid   = $db_data['user_id'] ?? 0; 

        $this->str  = (int)($db_data['attr_str'] ?? 0);
        $this->dex  = (int)($db_data['attr_agi'] ?? 0);
        $this->int  = (int)($db_data['attr_int'] ?? 0);
        $this->luck = (int)($db_data['attr_luck'] ?? 0);
        $this->wit  = (int)($db_data['attr_wit'] ?? 0);

        $qry = $db->prepare("SELECT * FROM tower_helper_items WHERE user_id = :id AND tower_helper = :cpycat AND item_type <= 10 AND slot <= 9");
        $qry->bindParam(':id', $this->uid);
        $qry->bindParam(':cpycat', $this->class);
        $qry->execute();
        $this->items = $qry->fetchAll(PDO::FETCH_ASSOC);

        $itemStats = array_fill(0, 7, 0);
        
        foreach ($this->items as $item) {
            $itemStats[$item['atr_type_1'] ?? 0] += $item['atr_val_1'] ?? 0;
            $itemStats[$item['atr_type_2'] ?? 0] += $item['atr_val_2'] ?? 0;
            $itemStats[$item['atr_type_3'] ?? 0] += $item['atr_val_3'] ?? 0;
        }

        $this->str  += ($itemStats[1] ?? 0) + ($itemStats[6] ?? 0);
        $this->dex  += ($itemStats[2] ?? 0) + ($itemStats[6] ?? 0);
        $this->int  += ($itemStats[3] ?? 0) + ($itemStats[6] ?? 0);
        $this->wit  += ($itemStats[4] ?? 0) + ($itemStats[6] ?? 0);
        $this->luck += ($itemStats[5] ?? 0) + ($itemStats[6] ?? 0);

        $this->armor = getCopycatRealArmor($this->uid, $this->class);
        
        $weapon = $this->getWeapon();
        $this->dmg = new stdClass();
        $this->dmg->min_damage = $weapon['dmg_min'] * (1 + $this->getPrimaryStatValue() / 10);
        $this->dmg->max_damage = $weapon['dmg_max'] * (1 + $this->getPrimaryStatValue() / 10);

        $k = 1; 
        switch ($this->class) {
            case 1:
                $k = 5;
                break;
            case 2:
                $k = 2;
                break;
            case 3:
                $k = 4;
                break;
        }
        
        $this->hp = $this->wit * $k * ($this->lvl + 1);
    }

    public function getId()
    {
        return $this->id;
    }

    public function getArmor($oponent)
    {
        $armor = getCopycatRealArmor($this->uid, $this->class) / $oponent->getLvl();
        
        if ($this->class == 1 && $armor > 50) $armor = 50;
        if ($this->class == 2 && $armor > 10) $armor = 10;
        if ($this->class == 3 && $armor > 25) $armor = 25;

        if ($oponent->getClass() == 2) {
            return 1;
        }
        
        return 1 - ($armor / 100);
    }

    public function getWeapon()
    {
        if (isset($this->items)) {
            foreach ($this->items as $item) {
                if ($item['slot'] == 9) {
                    return $item;
                }
            }
        }
        return [
            "item_type"  => 0, "item_id"   => 0, "dmg_min"    => 1, "dmg_max"    => 2,
            "atr_type_1" => 0, "atr_type_2" => 0, "atr_type_3" => 0,
            "atr_val_1"  => 0, "atr_val_2"  => 0, "atr_val_3"  => 0,
            "gold"       => 0, "mush"       => 0
        ];
    }

    public function getWeaponId()
    {
        $weap = $this->getWeapon();
        return (int)$weap['item_id'];
    }

    public function hasWeapon()
    {
        if (isset($this->items)) {
            foreach ($this->items as $item) {
                if ($item['slot'] == 9) return 1;
            }
        }
        return 0;
    }

    public function hasShield()
    {
        return 0;
    }

    public function getShield()
    {
        return [
            "item_type"  => 0, "item_id"   => 0, "dmg_min"    => 1, "dmg_max"    => 2,
            "atr_type_1" => 0, "atr_type_2" => 0, "atr_type_3" => 0,
            "atr_val_1"  => 0, "atr_val_2"  => 0, "atr_val_3"  => 0,
            "gold"       => 0, "mush"       => 0
        ];
    }
}

// gowno
class Album 
{
    public $data;
    private $contents;
    public $count;

    public function __construct($data, $count)
    {
		$this->data = $data;
		$this->count = $count;

		$this->decode();
    }

	private function decode()
	{
		$decoded = base64_decode(str_pad(strtr($this->data, '-_', '+/'), strlen($this->data) % 4, '=', STR_PAD_RIGHT));
		$byteArray = unpack('C*', $decoded);

		$this->contents = [];

		foreach($byteArray as $byte){
			$this->contents[] = ((($byte & 128) / 128) == 1);
			$this->contents[] = ((($byte & 64) / 64) == 1);
			$this->contents[] = ((($byte & 32) / 32) == 1);
			$this->contents[] = ((($byte & 16) / 16) == 1);
			$this->contents[] = ((($byte & 8) / 8) == 1);
			$this->contents[] = ((($byte & 4) / 4) == 1);
			$this->contents[] = ((($byte & 2) / 2) == 1);
			$this->contents[] = (($byte & 1) == 1);
		}
	}

	public function encode()
	{
		$s = "";
		$final = "";

		foreach($this->contents as $bool){
			$s .= $bool ? "1" : "0";
			if(strlen($s) == 8){
				$final .= pack('C*', bindec($s));
				$s = "";
			}
		}

		$this->data = strtr(base64_encode($final), '+/', '-_');
	}

	public function hasItem($item)
	{
		return $this->contents[$this->getItemIndex($item)];
	}

	public function addItem($item)
	{

		//if item is not an equipable, can be passed on using album, it's passing every item in possesion
		if($item['item_type'] > 10)
			return false;

		$index = Album::getItemIndex($item);

		if($this->contents[$index])
			return false;


		$this->contents[$index] = true;
		$this->count++;

		return true;
	}

	public function addItems($items)
    {
		$bool = false;

		foreach($items as $item){
			if($this->addItem($item))
				$bool = true;
		}

		return $bool;
	}

	public function hasMonster($id)
    {
		return $this->contents[abs($id) - 1];
	}

	public function addMonster($id)
    {
        $id = abs($id) - 1;
        if (($id < 0) || ($id > 252)) {
            return false;
        }

        if ($this->contents[$id]) {
            return false;
        }

        $this->contents[$id] = true;
        $this->count++;

		return true;
	}

	//color check removed at the bottom, returns first color index
	//add item at index and 4 after if not epic && not relic
    private static function getItemIndex($item)
    {
        $type = (int) ($item['item_type'] ?? 0);
        $rawId = (int) ($item['item_id'] ?? 0);
        
        $color = ((int)$item['dmg_min'] + (int)$item['dmg_max'] + (int)$item['atr_type_1'] + (int)$item['atr_type_2'] + (int)$item['atr_type_3'] + (int)$item['atr_val_1'] + (int)$item['atr_val_2'] + (int)$item['atr_val_3']) % 5;

        if ($type < 1 || $type > 10) {
            return 0; 
        }

        if ($type >= 8 && $type <= 10) {
            $forclass = 0;
        } else {
            $forclass = floor($rawId / 1000) + 1;
        }

        $id = $rawId;
        if ($forclass == 2) {
            $id -= 1000;
        }
        if ($forclass == 3) {
            $id -= 2000;
        }

        if ($id < 1 || $id > 57) {
            return 0;
        }

        $isEpic = (isset($item['quality']) && intval($item['quality']) == 1) || ($id >= 50);

        if ($isEpic || $type == 10) {
            $color = 0;
        }

        $index = 0;

        if ($forclass == 0) {
            switch ($type) {
                case 8:  $index = 300; break;
                case 9:  $index = 526; break;
                case 10: $index = 702; break;
            }
        } else if ($forclass == 1) {
            switch ($type) {
                case 1: $index = 792; break;
                case 2: $index = 1108; break;
                case 3: $index = 1224; break;
                case 4: $index = 1340; break;
                case 5: $index = 1456; break;
                case 6: $index = 1572; break;
                case 7: $index = 1688; break;
            }
        } else if ($forclass == 2) {
            switch ($type) {
                case 1: $index = 1804; break;
                case 3: $index = 1920; break;
                case 4: $index = 2036; break;
                case 5: $index = 2152; break;
                case 6: $index = 2268; break;
                case 7: $index = 2384; break;
            }
        } else if ($forclass == 3) {
            switch ($type) {
                case 1: $index = 2500; break;
                case 3: $index = 2616; break;
                case 4: $index = 2732; break;
                case 5: $index = 2848; break;
                case 6: $index = 2964; break;
                case 7: $index = 3080; break;
            }
        }

        if ($isEpic) {
            if ($type == 1 && $forclass == 1) {
                $index += 250;
            } elseif ($type == 1 && $forclass != 1) {
                $index += 50;
            } elseif ($type >= 2 && $type <= 7) {
                $index += 50;
            } elseif ($type == 8) {
                $index += 160;
            } elseif ($type == 9) {
                $index += 110;
            } elseif ($type == 10) {
                $index += 24;
            }
        }

        if ($isEpic) {
            $index += ($id - 50);
        } else if ($type == 10) { 
            $index += ($id - 1);
        } else { 
            $index += (($id - 1) * 5) + $color;
        }

        return $index;
    }

    public static function getDefaultData()
    {
        return 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA';
    }
}

function getQuestMonster($db_data): Monster
{
    $OP_lvl = ($db_data['lvl'] ?? 0) + rand(0, 2);
    $OP_class = rand(1, 3);
    
    $p = new Char($db_data);
    $weap = $p->getWeapon();
    
    $dmgMin = $weap['dmg_min'] ?? 0;
    $dmgMax = $weap['dmg_max'] ?? 0;
    
    if ($dmgMin && $dmgMax < 1) {
        $dmgMin = 1;
        $dmgMax = 1;
    }   

    $str = 0; 
    $agi = 0; 
    $int = 0; 
    $wit = 0; 
    $luck = 0;
    $mindmg = 0; 
    $maxdmg = 0; 
    $OP_health = 0;
    $armor = 0;
    $wpnid = -1;

    switch ($OP_class) {
        case 1: 
            $str  = ceil($p->getPrimaryStatValue() / (rand(200, 300) / 100));
            $agi  = ceil($p->getDex() / (rand(200, 300) / 100) / 4);
            $int  = ceil($p->getInt() / (rand(200, 300) / 100) / 4);
            $wit  = ceil($p->getWit() / (rand(200, 300) / 100));
            $luck = ceil($p->getLuck() / (rand(200, 300) / 100));
            
            $mindmg    = ceil($dmgMin * $p->getPrimaryStatValue() / 50);
            $maxdmg    = ceil($dmgMax * $p->getPrimaryStatValue() / 50);
            $OP_health = ceil($wit * 4 * ($OP_lvl + 1));
            
            $weapons = [-4, -2, -1];
            $wpnid   = $weapons[rand(0, 2)];
            break;

        case 2: 
            $str  = ceil($p->getStr() / (rand(200, 300) / 100) / 4);
            $agi  = ceil($p->getDex() / (rand(200, 300) / 100) / 4);
            $int  = ceil($p->getPrimaryStatValue() / (rand(200, 300) / 100));
            $wit  = ceil($p->getWit() / (rand(200, 300) / 100));
            $luck = ceil($p->getLuck() / (rand(200, 300) / 100));
            
            $mindmg    = ceil($dmgMin * $p->getPrimaryStatValue() / 40);
            $maxdmg    = ceil($dmgMax * $p->getPrimaryStatValue() / 40);
            $OP_health = ceil($wit * 2 * ($OP_lvl + 1));
            
            $weapons = [-2, -1, 1004];
            $wpnid   = $weapons[rand(0, 2)];
            break;

        case 3: 
            $str  = ceil($p->getStr() / (rand(200, 300) / 100) / 4);
            $agi  = ceil($p->getPrimaryStatValue() / (rand(200, 300) / 100));
            $int  = ceil($p->getInt() / (rand(200, 300) / 100) / 4);
            $wit  = ceil($p->getWit() / (rand(200, 300) / 100));
            $luck = ceil($p->getLuck() / (rand(200, 300) / 100));
            
            $mindmg    = ceil($dmgMin * $p->getPrimaryStatValue() / 45);
            $maxdmg    = ceil($dmgMax * $p->getPrimaryStatValue() / 45);
            $OP_health = ceil($wit * 3 * ($OP_lvl + 1));
            
            $weapons = [-4, -2, -1];
            $wpnid   = $weapons[rand(0, 2)];
            break;
    }

    $monster_id = rand(1, 158);
    $pq = $db_data['status_extra'] ?? 0;
    
    $questRedKey = 'quest_red_' . $pq;
    if (($db_data[$questRedKey] ?? 0) == 145) {
        $ids        = [139, 145, 148, 152, 155, 157];
        $monster_id = $ids[rand(0, 5)];
        $OP_health  = ceil($OP_health * 1.5);
        $wpnid      = -2;
    }

    return new Monster(
        $OP_lvl, 
        $OP_class, 
        $str, 
        $agi, 
        $int, 
        $wit, 
        $luck, 
        $mindmg, 
        $maxdmg, 
        $OP_health, 
        $armor, 
        $monster_id, 
        0, 
        $wpnid, 
        -1
    );
}

