function getStatCost($class, $race, $stat_index, $stat)
{
    $base = loadDefaultStats($class, $race);
    $stat -= ($base[$stat_index - 1] ?? 0);
    
    if ($stat < 0) {
        $stat = 0;
    }

    $attPriceLimitation = false;
    $GoldKurve = [0, 25, 50, 75];
    $TrueAttPreis = [];

    if ($stat <= 15000) {
        for ($i = 4; $i <= 15000; $i++) {
            $prevVal  = $GoldKurve[$i - 1] ?? 0;
            $halfVal  = $GoldKurve[(int)($i / 2)] ?? 0;
            $thirdVal = $GoldKurve[(int)($i / 3)] ?? 0;

            $curveCalc = $prevVal + (int)($halfVal / 3) + (int)($thirdVal / 4);
            $GoldKurve[$i] = (int)($curveCalc / 5) * 5;
        }

        for ($i = 0; $i <= 15000; $i++) {
            $TrueAttPreis[$i] = $GoldKurve[(int)(1 + ($i / 5))] ?? 0;
        }

        for ($i = 0; $i < 14996; $i++) {
            if ($attPriceLimitation) {
                $TrueAttPreis[$i] = 1000000000; 
            } else {
                $sum = (int)($TrueAttPreis[$i] ?? 0)
                     + (int)($TrueAttPreis[$i + 1] ?? 0)
                     + (int)($TrueAttPreis[$i + 2] ?? 0)
                     + (int)($TrueAttPreis[$i + 3] ?? 0)
                     + (int)($TrueAttPreis[$i + 4] ?? 0);

                $TrueAttPreis[$i] = (int)((int)($sum / 5) / 5) * 5;

                if ($TrueAttPreis[$i] > 1000000000) {
                    $TrueAttPreis[$i] = 1000000000;
                    $attPriceLimitation = true;
                }
            }
        }
    } else {
        $TrueAttPreis[$stat] = 1000000000;
    }

    return $TrueAttPreis[$stat] ?? 1000000000;
}

function mountCost($mount)
{
    global $MOUNT_10, $MOUNT_20, $MOUNT_30, $MOUNT_50;

    $ret = [];

    switch ($mount) {
        case $MOUNT_10:
            $ret['silver'] = 100;
            $ret['shroom'] = 0;
            break;
        case $MOUNT_20:
            $ret['silver'] = 500;
            $ret['shroom'] = 0;
            break;
        case $MOUNT_30:
            $ret['silver'] = 1000;
            $ret['shroom'] = 1;
            break;
        case $MOUNT_50:
            $ret['silver'] = 0;
            $ret['shroom'] = 25;
            break;
    }

    return $ret;
}

function loadDefaultStats($class, $race)
{
    global $CLASS_WARRIOR, $CLASS_MAGE, $CLASS_ROUGE;
    global $RACE_ORC, $RACE_ELF, $RACE_DARK_ELF, $RACE_DWARF, $RACE_GOBLIN, $RACE_GNOME, $RACE_DEMON;

    $ret = array_fill(0, 5, 10);

    switch ($class) {
        case $CLASS_WARRIOR:
            $ret[0] += 7;
            $ret[1] += 3;
            $ret[3] += 5;
            break;
        case $CLASS_MAGE:
            $ret[2] += 8;
            $ret[3] += 2;
            $ret[4] += 5;
            break;
        case $CLASS_ROUGE: 
            $ret[0] += 1;
            $ret[1] += 7;
            $ret[2] += 1;
            $ret[3] += 4;
            $ret[4] += 2;
            break;
    }

    switch ($race) {
        case $RACE_ORC:
            $ret[0] += 1;
            $ret[2] -= 1;
            break;
        case $RACE_ELF:
            $ret[0] -= 1;
            $ret[1] += 2;
            $ret[3] -= 1;
            break;
        case $RACE_DARK_ELF:
            $ret[0] -= 2;
            $ret[1] += 2;
            $ret[2] += 1;
            $ret[3] -= 1;
            break;
        case $RACE_DWARF:
            $ret[1] -= 2;
            $ret[2] -= 1;
            $ret[3] += 2;
            $ret[4] += 1;
            break;
        case $RACE_GOBLIN:
            $ret[0] -= 2;
            $ret[1] += 2;
            $ret[3] -= 1;
            $ret[4] += 1;
            break;
        case $RACE_GNOME:
            $ret[0] -= 2;
            $ret[1] += 3;
            $ret[2] -= 1;
            $ret[3] -= 1;
            $ret[4] += 1;
            break;
        case $RACE_DEMON:
            $ret[0] += 3;
            $ret[1] -= 1;
            $ret[3] += 1;
            $ret[4] -= 3;
            break;
        default:
            break;
    }

    return $ret;
}

function getGoldForWork($lvl)
{
    global $db;
        
    $qry = $db->prepare("SELECT * FROM game_settings WHERE setting IN ('WORK_MULTIPLIER') ORDER BY id ASC");
    $qry->execute();
    $res = $qry->fetchAll(PDO::FETCH_ASSOC);
    
    $m = $res[0]['value'] ?? 1; 

    $reward = (9 + round(pow($lvl, 3.04))) * $m;
    if ($reward > 100000000) {
        $reward = 100000000;
    }

    return $reward;
}

