    }
}

function getHp($db_data)
{
    $class = (int)($db_data['class'] ?? 1);
    
    $k = 1; 
    
    switch ($class) {
        case 1: $k = 5; break;
        case 2: $k = 2; break;
        case 3: $k = 4; break;
    }
    
    $wit = (int)($db_data['attr_wit'] ?? 0);
    $lvl = (int)($db_data['lvl'] ?? 0);

    return $wit * $k * ($lvl + 1);
}

