    global $SF_DMG_MIN, $SF_DMG_MAX, $SF_SERVERTIME, $SF_GUILD_WAR_STATUS, $SF_MOUNT, $SF_MOUNT_DURATION;
    global $SF_QUEST_RED_1, $SF_QUEST_RED_2, $SF_QUEST_RED_3;
    global $SF_QUEST_DURATION_1, $SF_QUEST_EXP_1, $SF_QUEST_DURATION_2, $SF_QUEST_EXP_2, $SF_QUEST_DURATION_3, $SF_QUEST_EXP_3;
    global $SF_QUEST_GOLD_1, $SF_QUEST_GOLD_2, $SF_QUEST_GOLD_3, $SF_MUSHROOMS_MAY_DONATE;
    global $SF_QUEST_DESC_1, $SF_QUEST_DESC_2, $SF_QUEST_DESC_3;

    $time = time(); 
    $db_data = [];

    if (func_num_args() !== 1) {
        $qry = $db->prepare("SELECT user_data.*, guilds.treasure, guilds.instructor, guilds.dung, guilds.portal_act AS g_act, guilds.portal_monster AS g_monster, 
            (SELECT Count(*) FROM messages WHERE messages.read = 0 AND messages.reciver_id = user_data.user_id) AS c, 
            (SELECT Count(*) FROM messages WHERE messages.reciver_id = user_data.user_id) AS mcount,
            (SELECT attack_time FROM guild_attacks WHERE guild_id = (SELECT guild_id FROM user_data WHERE ssid = :ssid1 LIMIT 1) LIMIT 1) AS atcktime,
            (SELECT attack_time FROM guild_attacks WHERE target_id = (SELECT guild_id FROM user_data WHERE ssid = :ssid2 LIMIT 1) LIMIT 1) AS deftime,
            (SELECT pos FROM (
                SELECT honor, lvl, user_name, ssid, user_id, @r:=@r+1 as pos
                FROM user_data, (SELECT @r:=0) r0
                ORDER BY honor DESC, lvl DESC, user_id DESC
            ) user_data_ordered WHERE ssid = :ssid3 LIMIT 1) AS rank,
            (SELECT COUNT(*) FROM user_fights WHERE DATE(fight_time) = CURDATE() AND user_fights.user_id = user_data.user_id) AS fcount
            FROM user_data 
            LEFT JOIN guilds ON user_data.guild_id = guilds.guild_id 
            WHERE ssid = :ssid4 LIMIT 1");
        
        $qry->execute([
            ':ssid1' => $SSID,
            ':ssid2' => $SSID,
            ':ssid3' => $SSID,
            ':ssid4' => $SSID
        ]);
        $db_data = $qry->fetch(PDO::FETCH_ASSOC) ?? [];
    } else {
        $db_data = func_get_arg(0);
    }   

    $ttime = strtotime('today');
    $HP = (int)($db_data['portal_hp'] ?? 0);
    $portalAct = (int)($db_data['portal_act'] ?? 1);
    $portalMonster = (int)($db_data['portal_monster'] ?? 1);
    
    $monster = getPortalMonster($portalAct, $portalMonster);
    $fullHP = $monster->getHP();
    $portalRegenTime = (int)($db_data['portal_regen_time'] ?? 0);

    if ($ttime > $portalRegenTime && $HP != $fullHP) {
        $days = ($ttime - $portalRegenTime) / 86400;
        $HP = (int)($HP + (($days * 10) / 100) * $fullHP); 
        if ($HP > $fullHP) {
            $HP = $fullHP;
        }
        $db_data['portal_regen_time'] = $ttime;
        $db_data['portal_hp'] = $HP;
        
        $qry = $db->prepare("UPDATE user_data SET portal_regen_time = :time, portal_hp = :hp WHERE ssid = :ssid");
        $qry->execute([':ssid' => $SSID, ':time' => $ttime, ':hp' => $HP]);
    }

    if (($db_data['silver'] ?? 0) < 0) {
        $db_data['silver'] = 0;
