    }

    $magicMirror = (string)($db_data['magic_mirror'] ?? '0000000000000');
    $gender = ''; 
    
    if ($magicMirror === '1111111111111') {
        $haveMirror = '1';
    } elseif ($magicMirror === '0000000000000') {
        $haveMirror = '0';
    } else {
        $gender = '1'; 
        $gender .= $magicMirror;
        $haveMirror = '0';
    }
    
    $gender .= '000000000' . $haveMirror . '0000000';
    $gender .= (($db_data['gender'] ?? 1) == 1) ? '1' : '0';

