    $mount = mountMultiplier($db_data['mount'] ?? 0);

    $ebonus = 1 + ((int)($db_data['instructor'] ?? 0) + (int)($db_data['dung'] ?? 0)) / 50;
    $gbonus = 1 + ((int)($db_data['treasure'] ?? 0) + (int)($db_data['dung'] ?? 0)) / 50;
