function event()
{
    global $db;

    $qry = $db->prepare("SELECT value FROM server_config WHERE name = 'EVENT' LIMIT 1");
    $qry->execute();
    $res = $qry->fetch(PDO::FETCH_ASSOC);

    return (int)($res['value'] ?? 0);
}

function loadCharData($db_data)
{
    global $db, $ret, $LEVELS;
    global $SF_PLAYER_ID, $SF_EXP, $SF_EXP_REQ, $SF_HONOR, $SF_RANK, $SF_LEVEL;
    global $SF_ACHIEVEMENT_LVL, $SF_ACHIEVEMENT_ARENA, $SF_ACHIEVEMENT_QUEST, $SF_ACHIEVEMENT_WORK;
    global $SF_ACHIEVEMENT_GOLD, $SF_ACHIEVEMENT_HONOR, $SF_ACHIEVEMENT_DUNG;
    global $SF_ATTR_STR, $SF_ATTR_AGI, $SF_ATTR_INT, $SF_ATTR_WIT, $SF_ATTR_LUCK;
    global $SF_FACE_1, $SF_FACE_10, $SF_RACE, $SF_GENDER, $SF_CLASS, $SF_DMG_MIN, $SF_DMG_MAX, $SF_MOUNT;

    $time = time(); 
    $ret[0] = "1110000000000";

    $qry = $db->prepare("SELECT * FROM guilds WHERE guild_id = :gid LIMIT 1");
    $qry->execute([':gid' => $db_data['guild_id'] ?? 0]);
    $guild_data = $qry->fetch(PDO::FETCH_ASSOC) ?? [];

    $portalLifeBonus = ((int)($db_data['portal_monster'] ?? 1) + (((int)($db_data['portal_act'] ?? 1) - 1) * 10) - 1) * 256; 
    $portalDamageBonus = ((int)($guild_data['portal_monster'] ?? 1) + (((int)($guild_data['portal_act'] ?? 1) - 1) * 10) - 1) + $portalLifeBonus; 
    
    if (($db_data['guild_id'] ?? 0) != 0) {
        $ret[445] = $portalDamageBonus * 65536; 
    } else {
        $ret[445] = $portalLifeBonus * 65536;    
    }

    $ret[$SF_PLAYER_ID] = $db_data['user_id'] ?? 0;
    $ret[$SF_EXP]       = $db_data['exp'] ?? 0;
    $ret[$SF_EXP_REQ]   = $LEVELS[$db_data['lvl'] ?? 1] ?? 0;
    $ret[$SF_HONOR]     = $db_data['honor'] ?? 0;
    $ret[$SF_RANK]      = $db_data['rank'] ?? 1;
    $ret[$SF_LEVEL]     = $db_data['lvl'] ?? 1;

    $ret[$SF_ACHIEVEMENT_LVL]   = $db_data['lvl'] ?? 1;
    $ret[$SF_ACHIEVEMENT_ARENA] = $db_data['medal_gladiator'] ?? 0;
    $ret[$SF_ACHIEVEMENT_QUEST] = $db_data['medal_adventurer'] ?? 0;
    $ret[$SF_ACHIEVEMENT_WORK]  = $db_data['medal_employment'] ?? 0;
    $ret[$SF_ACHIEVEMENT_GOLD]  = $db_data['medal_commerce'] ?? 0;
    $ret[$SF_ACHIEVEMENT_HONOR] = $db_data['medal_bravery'] ?? 0;

    $sum = 0;
    for ($d = 1; $d <= 13; $d++) {
        $a = (int)($db_data['dungeon_' . $d] ?? 0);
        if ($a > 2) {
            $sum += ($a - 2);
        }
    }
    $ret[$SF_ACHIEVEMENT_DUNG] = $sum;

    $towerLvl = (int)($db_data['tower_level'] ?? 1);
    $ret[512] = $towerLvl - 1;
    $ret[286] = ($towerLvl - 1) * 65536; 

    $ret[$SF_ATTR_STR]  = $db_data['attr_str'] ?? 10;
    $ret[$SF_ATTR_AGI]  = $db_data['attr_agi'] ?? 10;
    $ret[$SF_ATTR_INT]  = $db_data['attr_int'] ?? 10;
    $ret[$SF_ATTR_WIT]  = $db_data['attr_wit'] ?? 10;
    $ret[$SF_ATTR_LUCK] = $db_data['attr_luck'] ?? 10;

    $faceStart = (int)$SF_FACE_1;
    $faceEnd   = (int)$SF_FACE_10;
    for ($f = $faceStart; $f <= $faceEnd; $f++) {
        $ret[$f] = $db_data['face' . ($f - 16)] ?? 0;
    }

    $ret[$SF_RACE]   = $db_data['race'] ?? 1;
    $ret[$SF_GENDER] = $db_data['gender'] ?? 1;
    $ret[$SF_CLASS]  = $db_data['class'] ?? 1;

    $qry = $db->prepare("SELECT * FROM items WHERE owner_id = :id AND slot < 10");
    $qry->execute([':id' => $db_data['user_id'] ?? 0]);
    $items = $qry->fetchAll(PDO::FETCH_ASSOC);

    foreach ($items as &$item) {
        $slotIdx = (int)$item['slot'];
        if ($slotIdx < 10) {
            $item['slot'] = 48 + ($slotIdx * 12);
        } else {
            $item['slot'] = 168 + (($slotIdx - 10) * 12);
        }
    }
    unset($item); 

    $ret[$SF_DMG_MIN] = 1;
    $ret[$SF_DMG_MAX] = 2;

    foreach ($items as $item) {
        $targetSlot = (int)$item['slot'];
        
        $ret[$targetSlot]      = (int)($item['enchant'] ?? 0) + (int)($item['item_type'] ?? 0);
        $ret[$targetSlot + 1]  = (int)($item['enchant_power'] ?? 0) + (int)($item['item_id'] ?? 0);
        $ret[$targetSlot + 2]  = $item['dmg_min'] ?? 0;
        $ret[$targetSlot + 3]  = $item['dmg_max'] ?? 0;
        $ret[$targetSlot + 4]  = $item['atr_type_1'] ?? 0;
        $ret[$targetSlot + 5]  = $item['atr_type_2'] ?? 0;
        $ret[$targetSlot + 6]  = $item['atr_type_3'] ?? 0;
        $ret[$targetSlot + 7]  = $item['atr_val_1'] ?? 0;
        $ret[$targetSlot + 8]  = $item['atr_val_2'] ?? 0;
        $ret[$targetSlot + 9]  = $item['atr_val_3'] ?? 0;
        $ret[$targetSlot + 10] = $item['gold'] ?? 0;
        $ret[$targetSlot + 11] = ($item['mush'] ?? 0) + (($item['upgrade_level'] ?? 0) * 16777216);

        if ($targetSlot < 168) {
            $atrType1 = (int)($item['atr_type_1'] ?? 0);
            $atrType2 = (int)($item['atr_type_2'] ?? 0);
            $atrType3 = (int)($item['atr_type_3'] ?? 0);

            if ($atrType1 === 6) {
                for ($k = 0; $k < 5; $k++) {
                    $ret[35 + $k] = ($ret[35 + $k] ?? 0) + ($item['atr_val_1'] ?? 0);
                }
            } else {
                if ($atrType1 > 0) $ret[34 + $atrType1] = ($ret[34 + $atrType1] ?? 0) + ($item['atr_val_1'] ?? 0);
                if ($atrType2 > 0) $ret[34 + $atrType2] = ($ret[34 + $atrType2] ?? 0) + ($item['atr_val_2'] ?? 0);
                if ($atrType3 > 0) $ret[34 + $atrType3] = ($ret[34 + $atrType3] ?? 0) + ($item['atr_val_3'] ?? 0);
            }
        }

        if ((int)($item['item_type'] ?? 0) == 1 && $targetSlot = 150) {
            $ret[$SF_DMG_MIN] = $item['dmg_min'] ?? 1;
            $ret[$SF_DMG_MAX] = $item['dmg_max'] ?? 2;
        }
    }

    $ret[447] = getRealArmor($db_data['user_id'] ?? 0);
    
    $desc = fixSpecialChars(urldecode($db_data['user_desc'] ?? ''));
    $guildName = $db_data['guild'] ?? '';
    
    $ret[511] = $time . ";" . $desc . ";" . $guildName;

    $ret[499] = $db_data['potion_value1'] ?? 0; 
    $ret[500] = $db_data['potion_value2'] ?? 0; 
    $ret[501] = $db_data['potion_value3'] ?? 0; 
    $ret[493] = $db_data['potion_id1'] ?? 0; 
    $ret[494] = $db_data['potion_id2'] ?? 0; 
    $ret[495] = $db_data['potion_id3'] ?? 0; 
    $ret[496] = $db_data['potion_time1'] ?? 0; 
    $ret[497] = $db_data['potion_time2'] ?? 0; 
    $ret[498] = $db_data['potion_time3'] ?? 0; 
    $ret[444] = $db_data['golden_frame'] ?? 0;

    $album = (int)($db_data['album'] ?? 0);
    $ret[438] = $album == -1 ? 0 : 10000 + $album;

    for ($p = 1; $p < 4; $p++) {
        $potionId = (int)($db_data['potion_id' . $p] ?? 0);
        switch ($potionId) {
            case 1:  $ret[35] = ($ret[35] ?? 0) + (($ret[35] ?? 0) + ($ret[30] ?? 0)) * 0.10; break;
            case 2:  $ret[36] = ($ret[36] ?? 0) + (($ret[36] ?? 0) + ($ret[31] ?? 0)) * 0.10; break;
            case 3:  $ret[37] = ($ret[37] ?? 0) + (($ret[37] ?? 0) + ($ret[32] ?? 0)) * 0.10; break;
            case 4:  $ret[38] = ($ret[38] ?? 0) + (($ret[38] ?? 0) + ($ret[33] ?? 0)) * 0.10; break;
            case 5:  $ret[39] = ($ret[39] ?? 0) + (($ret[39] ?? 0) + ($ret[34] ?? 0)) * 0.10; break;
            case 6:  $ret[35] = ($ret[35] ?? 0) + (($ret[35] ?? 0) + ($ret[30] ?? 0)) * 0.15; break;
            case 7:  $ret[36] = ($ret[36] ?? 0) + (($ret[36] ?? 0) + ($ret[31] ?? 0)) * 0.15; break;
            case 8:  $ret[37] = ($ret[37] ?? 0) + (($ret[37] ?? 0) + ($ret[32] ?? 0)) * 0.15; break;
            case 9:  $ret[38] = ($ret[38] ?? 0) + (($ret[38] ?? 0) + ($ret[33] ?? 0)) * 0.15; break;
            case 10: $ret[39] = ($ret[39] ?? 0) + (($ret[39] ?? 0) + ($ret[34] ?? 0)) * 0.15; break;
            case 11: $ret[35] = ($ret[35] ?? 0) + (($ret[35] ?? 0) + ($ret[30] ?? 0)) * 0.25; break;
            case 12: $ret[36] = ($ret[36] ?? 0) + (($ret[36] ?? 0) + ($ret[31] ?? 0)) * 0.25; break;
            case 13: $ret[37] = ($ret[37] ?? 0) + (($ret[37] ?? 0) + ($ret[32] ?? 0)) * 0.25; break;
            case 14: $ret[38] = ($ret[38] ?? 0) + (($ret[38] ?? 0) + ($ret[33] ?? 0)) * 0.25; break;
            case 15: $ret[39] = ($ret[39] ?? 0) + (($ret[39] ?? 0) + ($ret[34] ?? 0)) * 0.25; break;
        }
    }    

    $ret[511] .= ";" . $desc . ";";

    if ($time < (int)($db_data['mount_dur'] ?? 0)) {
        $ret[$SF_MOUNT] = ($towerLvl - 1) * 65536 + (int)($db_data['mount'] ?? 0); 
    }
}

function check_for_key($ssid)
{
    global $db;

    $uqry = $db->prepare("SELECT user_id FROM user_data WHERE ssid = :ssid LIMIT 1");
    $uqry->execute([':ssid' => $ssid]);
    $user = $uqry->fetch(PDO::FETCH_ASSOC);

    if (!$user) {
        return "nonono";
    }

    $uid = $user['user_id'];
    $qry = $db->prepare("SELECT item_id FROM `items` WHERE slot > 9 AND slot < 15 AND item_type = 11 AND owner_id = :uid LIMIT 1");
    $qry->execute([':uid' => $uid]);

    if ($qry->rowCount() == 0) {
        return "go";
    }

    return "nonono";
}

function getRealArmor(int $uid)
{
    global $db;

    $qry = $db->prepare("SELECT SUM(dmg_min) as armor FROM `items` WHERE owner_id = :uid AND slot IN (0, 1, 2, 3, 5)");
    $qry->execute([':uid' => $uid]);
    $armor = $qry->fetch(PDO::FETCH_ASSOC);

    return max(0, (int)($armor['armor'] ?? 0));
}

function getCopycatRealArmor(int $uid, int $copycat)
{
    global $db;

    $qry = $db->prepare("SELECT SUM(dmg_min) as armor FROM `tower_helper_items` WHERE user_id = :uid AND tower_helper = :cpycat AND slot IN (0, 1, 2, 3, 5)");
    $qry->execute([':uid' => $uid, ':cpycat' => $copycat]);
    $armor = $qry->fetch(PDO::FETCH_ASSOC);

    return max(0, (int)($armor['armor'] ?? 0));
}

function getCopycatWeapon(int $uid, int $copycat)
{
    global $db;

    $qry = $db->prepare("SELECT * FROM `tower_helper_items` WHERE slot = 9 AND user_id = :uid AND tower_helper = :cpycat LIMIT 1");
    $qry->execute([':uid' => $uid, ':cpycat' => $copycat]);
    
    return $qry->fetch(PDO::FETCH_ASSOC) ?? [];
}   

function getFillLevel(int $aura)
{
    return ($aura < 18) ? (100 + $aura * 50) : 1000;
}

function loadGuildData($g_data, array $m_data, array $im_data, array $war_data, $pos, bool $member_of, string $ssid)
{
    global $db, $ret;

    $fightCost = 0; 

    $qry = $db->prepare("SELECT guild_id FROM user_data WHERE ssid = :ssid LIMIT 1");
    $qry->execute([':ssid' => $ssid]);
    $user_guild_row = $qry->fetch(PDO::FETCH_NUM);
    $user_guild_id = $user_guild_row[0] ?? 0;

    $ret = array_fill(0, 372, 0);
    $mc = count($m_data);
    $imc = count($im_data);
    
    $guildId = $g_data['guild_id'] ?? 0;
    $ret[0] = $member_of ? "006" . $guildId : "172" . $guildId;

    if ($member_of) {
        $ret[1] = $g_data['silver'] ?? 0;
        $ret[2] = (65536 * ($g_data['portal_act'] ?? 1)) + ($g_data['mushroom'] ?? 0);
        
        $HP = (int)($g_data['portal_hp'] ?? 0);
        $lifeLo = 0;
        $lifeHi = $HP;
        
        if ($HP > 65535) {
            $lifeHi = 65535;
            $lifeLo = $HP - 65535;
        }
        
        $ret[4] = ($lifeLo * 65536) + ($g_data['catapult'] ?? 0);
        $ret[5] = ($lifeHi * 65536) + ($g_data['fortress'] ?? 0);
        
        $monster = getGuildPortalMonster($g_data['portal_act'] ?? 1, $g_data['portal_monster'] ?? 1);
        $fullHP = $monster->getHP();
        
        $percents = ($fullHP > 0) ? round(($HP / $fullHP) * 100) : 1;
        if ($percents < 1) {
            $percents = 1;
        }
        
        $ret[6] = ($percents * 65536) + ($g_data['treasure'] ?? 0);
        
        $monsterIdx = (($g_data['portal_monster'] ?? 1) - 1) + (($g_data['portal_act'] ?? 1) - 1) * 10;
        $ret[7] = ($monsterIdx * 65536) + ($g_data['instructor'] ?? 0);
    }

    $ret[3] = $mc + $imc;
    $ret[8] = $g_data['dung'] ?? 0;
    $ret[9] = (($war_data[0]['target_id'] ?? 0) == 1000000) ? 1 : 0;
    $ret[10] = 2;
    $ret[11] = 1407846286; 
    $ret[12] = 1407846286;
    $ret[13] = $g_data['honor'] ?? 0;

    $index = 14;
    for ($i = 0; $i < $mc; $i++) {
        $ret[$index++] = $m_data[$i]['user_id'] ?? 0;
    }
    for ($i = 0; $i < $imc; $i++) {
        $ret[$index++] = $im_data[$i]['user_id'] ?? 0;
    }

    $index = 64;
    for ($i = 0; $i < $mc; $i++) {
        $status = 0;
        $mAttack = $m_data[$i]['guild_attack'] ?? '0';
        $mDefend = $m_data[$i]['guild_defend'] ?? '0';

        if ($mAttack === "1" && $mDefend === "0") $status = 1;
        elseif ($mAttack === "0" && $mDefend === "1") $status = 2;
        elseif ($mAttack === "1" && $mDefend === "1") $status = 3;

        $playerLvl = (int)($m_data[$i]['lvl'] ?? 1);
        $nulls = ($playerLvl < 10) ? (3 - strlen((string)$playerLvl)) : 1;

        $ret2 = (string)$status;
        for ($c = 0; $c < $nulls; $c++) {
            $ret2 .= '0';
        }
        
        $ret[$index++] = $ret2 . $playerLvl;
    }

    for ($i = 0; $i < $imc; $i++) {
        $ret[$index++] = (int)($im_data[$i]['lvl'] ?? 1);
    }

    if ($member_of) {
        $index = 114;
        for ($i = 0; $i < $mc; $i++) {
            $ret[$index++] = $m_data[$i]['last_activ'] ?? 0;
        }
        $index = 164;
        for ($i = 0; $i < $mc; $i++) {
            $ret[$index++] = $m_data[$i]['guild_portal'] ?? 0;
        }
        $index = 214;
        for ($i = 0; $i < $mc; $i++) {
            $ret[$index++] = $m_data[$i]['g_silverspent'] ?? 0;
        }
        $index = 264;
        for ($i = 0; $i < $mc; $i++) {
            $ret[$index++] = $m_data[$i]['g_mushroomspent'] ?? 0;
        }
    }

    $index = 314;
    for ($i = 0; $i < $mc; $i++) {
        $ret[$index++] = $m_data[$i]['guild_rank'] ?? 3;
    }
    for ($i = 0; $i < $imc; $i++) {
        $ret[$index++] = 4; 
    }

    $index = 364;
    $gIdVal = (int)($g_data['guild_id'] ?? 0);

    if ((int)($war_data[0]['guild_id'] ?? 0) === $gIdVal) {
        $ret[$index]     = $war_data[0]['target_id'] ?? 0;
        $ret[$index + 1] = $war_data[0]['attack_time'] ?? 0;
    } elseif ((int)($war_data[1]['guild_id'] ?? 0) === $gIdVal) {
        $ret[$index]     = $war_data[1]['target_id'] ?? 0;
        $ret[$index + 1] = $war_data[1]['attack_time'] ?? 0;
    } else {
        $ret[$index]     = 0;
        $ret[$index + 1] = 0;
    }

    if ((int)($war_data[0]['target_id'] ?? 0) === $gIdVal) {
        $ret[$index + 2] = $war_data[0]['guild_id'] ?? 0;
        $ret[$index + 3] = $war_data[0]['attack_time'] ?? 0;
    } elseif ((int)($war_data[1]['target_id'] ?? 0) === $gIdVal) {
        $ret[$index + 2] = $war_data[1]['guild_id'] ?? 0;
        $ret[$index + 3] = $war_data[1]['attack_time'] ?? 0;
    } else {
        $ret[$index + 2] = 0;
        $ret[$index + 3] = 0;
    }

    $ret[$index + 4] = "0";
    $ret[$index + 5] = "0";
    $ret[$index + 6] = time() . ';' . ($g_data['coatofarms'] ?? '') . '§' . fixSpecialChars(urldecode($g_data['description'] ?? '')) . ';';
    
    $index += 7;
    for ($i = 0; $i < $mc; $i++) {
        $ret[$index++] = $m_data[$i]['user_name'] ?? 'Unknown';
    }
    for ($i = 0; $i < $imc; $i++) {
        $ret[$index++] = $im_data[$i]['user_name'] ?? 'Unknown';
    }

    if (!$member_of) {
        $fightCost = getGuildWarCost((int)($g_data['fortress'] ?? 10)) * 100;
    }

    $ret[$index - 1] = ($ret[$index - 1] ?? '') . ';' . ($g_data['name'] ?? '') . ';' . ($g_data['honor'] ?? 0) . ';' . ($g_data['rank'] ?? 1) . $pos . ';' . $fightCost;
    
    $GLOBALS['ret'] = $ret;
}

