function fixSpecialChars(string $text)
{
    $search = [
        '%u016F', '%u010D', '%u011B', '%u0161', '%u0159', '%u017E', '%u010F', '%u0148', '%FD', '%u011A',
        '%u0160', '%u010C', '%u0158', '%u017D', '%u010E', '%u0147', '%u016E', '%u0165', '%u0164', '%DD'
    ];
    $replace = [
        'ů', 'č', 'ě', 'š', 'ř', 'ž', 'ď', 'ň', 'ý', 'Ě',
        'Š', 'Č', 'Ř', 'Ž', 'Ď', 'Ň', 'Ů', 'ť', 'Ť', 'Ý'
    ];

    return str_replace($search, $replace, $text);
}

function createMessageFormat($messages, int $countAll)
{
    $count = count($messages);
    if ($count > 5) {
        $count = 5;
    }

    $msgs = [];
    if ($count === 1) {
        $count = 0;
        $msgs[] = "161" . ($messages[$count] ?? '') . ";" . $countAll . ";;" . $countAll;
    } else {
        $msgs[] = "161" . ($messages[0] ?? '');
    }

    for ($i = 1; $i < $count; $i++) {
        if ($i !== ($count - 1)) {
            $msgs[] = $messages[$i] ?? '';
        } elseif ($count !== 0) {
            $msgs[] = ($messages[$i] ?? '') . ";" . $countAll . ";;" . $countAll;
        }
    }

    for ($i = 1; $i < $count; $i++) {
        if (($countAll - $i) !== 0) {
            $msgs[] = ($countAll - $i);
        }
    }

    return $msgs;
}

function nextPlayer(&$player, array $list, int $listPos)
{
    global $lastcount1, $lastcount2; 

    if ($listPos === 1) {
        $lastcount1++;
        if (count($list) > $lastcount1) {
            $player = new Char($list[$lastcount1]);
        }
    } else {
        $lastcount2++;
        if (count($list) > $lastcount1) {
            $player = new Char($list[$lastcount2]);
            if ((int)($list[$lastcount2]['guild_defend'] ?? 0) === 0) {
                $hp = (int)($player->getHp() / 2);
                $player->setHP($hp);
            }
        }
    }
}

function nextRaidFighter(&$op, $list, int $listPos, int $dung)
{
    global $lastcount1, $lastcount2;

    if ($listPos === 1) {
        $lastcount1++;
        if (count($list) > $lastcount1) {
            $op = new Char($list[$lastcount1]);
        }
    } else {
        $lastcount2++;
        if ($list > $lastcount1) {
            $op = getRaidMonster($dung, $lastcount2);
        }
    }
}

function generateRaidBattle($guild, $battleType)
