    $qry->execute([':gid' => $guild]);
    $g1_m = $qry->fetchAll(PDO::FETCH_ASSOC);

    $qry = $db->prepare("SELECT * FROM guilds WHERE guild_id = :gid LIMIT 1");
    $qry->execute([':gid' => $guild]);
    $guildData = $qry->fetch(PDO::FETCH_ASSOC);

    if (!$guildData) {
        return ['', '', false];
    }

    if ((int)($guildData['dung'] ?? 0) === 50) {
        return ['', '', false];
    }  

    $dungLvl = (int)($guildData['dung'] ?? 0);
    if ($dungLvl === 0) {
        $rounds = 12;
    } elseif ($dungLvl === 1) {
        $rounds = 14;
    } else {
        $rounds = 15;
    }

    $charP1 = null;
    $charOP = null;

