function generateGuildBattle($firstGuild, $secondGuild, $battleType)
{
    global $db, $lastcount1, $lastcount2;

    $ret = ''; 
    $ret2 = '';

    $qry = $db->prepare("SELECT * FROM user_data WHERE guild_id = :gid AND guild_attack = 1 ORDER BY lvl ASC");
    $qry->execute([':gid' => $firstGuild]);
    $g1_m = $qry->fetchAll(PDO::FETCH_ASSOC);

    $qry = $db->prepare("SELECT * FROM user_data WHERE guild_id = :gid ORDER BY lvl ASC");
    $qry->execute([':gid' => $secondGuild]);
    $g2_m = $qry->fetchAll(PDO::FETCH_ASSOC);

    $qry = $db->prepare("SELECT name FROM guilds WHERE guild_id = :gid LIMIT 1");
    $qry->execute([':gid' => $firstGuild]);
    $g1 = $qry->fetch(PDO::FETCH_ASSOC);
    $g1_name = $g1['name'] ?? 'Attacker';

    $qry = $db->prepare("SELECT * FROM guilds WHERE guild_id = :gid LIMIT 1");
    $qry->execute([':gid' => $secondGuild]);
    $g2 = $qry->fetch(PDO::FETCH_ASSOC);
    $g2_name = $g2['name'] ?? 'Defender';

    $charP1 = null;
    $charOP = null;

    while (count($g1_m) > $lastcount1 && count($g2_m) > $lastcount2) {
        $retTemp = [];
