        $last2 = $lastcount2;
        
        $charP11 = new Char($g1_m[$last1]);
        $charOP1 = new Char($g2_m[$last2]);

        if (($last1 + $last2) === 0) {
            $charP1 = new Char($g1_m[$last1]);
            $charOP = new Char($g2_m[$last2]);
            if ((int)($g2_m[$last2]['guild_defend'] ?? 0) === 0) {
                $hp = (int)($charOP->getHp() / 2);
                $charOP->setHP($hp);
            }
        }

        if (!$charP1 || !$charOP) {
            break;
        }

