        $retTemp[] = $charOP1->getHp();
        array_push($retTemp, $charOP->getStr(), $charOP->getDex(), $charOP->getInt(), $charOP->getWit(), $charOP->getLuck());

        $h1 = (($charP11->getHp() - $charP1->getHp()) !== 0) ? $charP1->getHp() : -1;
        $h2 = (($charOP1->getHp() - $charOP->getHp()) !== 0) ? $charOP->getHp() : -1;  

        $sim = SF_Calc::calculateWin($charP1, $charOP, 'pvp');
        $win = $charP1->getHP() > 0;
        
        $retTemp[count($retTemp) - 1] .= ";" . ($sim[0][0] ?? 0);
        $retTemp[] = $sim[0][1] ?? 0;
        $retTemp[] = $sim[0][1] ?? 0;
        
        $simCount = count($sim);
        for ($i = 1; $i < $simCount; $i++) {
            array_push($retTemp, $sim[$i][0] ?? 0, $sim[$i][1] ?? 0, $sim[$i][2] ?? 0);
        }

        $retTemp[count($retTemp) - 1] = ";" . ($g1_m[$last1]['user_name'] ?? 'Unknown');
        array_push($retTemp, $g1_m[$last1]['lvl'] ?? 1, $g1_m[$last1]['race'] ?? 1, $g1_m[$last1]['gender'] ?? 1, $g1_m[$last1]['class'] ?? 1);
        
        for ($a = 1; $a <= 10; $a++) {
            $retTemp[] = $g1_m[$last1]['face' . $a] ?? 0;
        }

        array_push($retTemp, $g2_m[$last2]['user_name'] ?? 'Unknown', $g2_m[$last2]['lvl'] ?? 1, $g2_m[$last2]['race'] ?? 1, $g2_m[$last2]['gender'] ?? 1, $g2_m[$last2]['class'] ?? 1);
        
        for ($a = 1; $a <= 10; $a++) {
            $retTemp[] = $g2_m[$last2]['face' . $a] ?? 0;
        }

        $retTemp[count($retTemp) - 1] .= ";" . $charP1->hasWeapon(); 
        
        $weap = $charP1->getWeapon();
        array_push($retTemp, $weap['item_id'] ?? 0, $weap['dmg_min'] ?? 0, $weap['dmg_max'] ?? 0, $weap['atr_type_1'] ?? 0, $weap['atr_type_2'] ?? 0, $weap['atr_type_3'] ?? 0, $weap['atr_val_1'] ?? 0, $weap['atr_val_2'] ?? 0, $weap['atr_val_3'] ?? 0, $weap['gold'] ?? 0, $weap['mush'] ?? 0);
        
        $weap = $charOP->getWeapon();
