}

function changeItem($item)
{
    $itemType = (int)($item['item_type'] ?? 0);
    $itemId   = (int)($item['item_id'] ?? 0);

    if ($itemType !== 2 && $itemType < 8) {     
        $oldClass = (int)round($itemId / 1000) + 1;
        $class = rand(1, 3);
        while ($class === $oldClass) {
            $class = rand(1, 3);
        }
        
        $itemId = $itemId - (1000 * ($oldClass - 1)) + (1000 * ($class - 1));
        $item['item_id'] = $itemId;

        if ($itemId < 1049 && $itemId > 1010) {
            $item['item_id'] = rand(1008, 1010); 
        } elseif ($itemId < 2049 && $itemId > 2010) {
            $item['item_id'] = rand(2008, 2010);
        }

        if ($itemType !== 1) {
            $dmgMin = (int)($item['dmg_min'] ?? 0);
            switch ($oldClass) {
                case 1: $dmgMin = round($dmgMin / 5); break;
                case 2: $dmgMin = round($dmgMin / 1); break;
                case 3: $dmgMin = round($dmgMin / 3); break;
            }
            switch ($class) {
                case 1: $dmgMin = round($dmgMin * 5); break;
                case 2: $dmgMin = round($dmgMin * 1); break;
                case 3: $dmgMin = round($dmgMin * 3); break;
            }
            $item['dmg_min'] = $dmgMin;
        }
    }

    $newid = (int)($item['item_id'] ?? 0);
    $ntype = (int)($item['item_type'] ?? 0);
    $stat  = (int)($item['atr_type_1'] ?? 0);
    
    $newstat = 1; 

    if ($stat === 1) {
        $newstat = (rand(1, 2) === 1) ? 2 : 3;
    } elseif ($stat === 2) {
        $newstat = (rand(1, 2) === 1) ? 1 : 3;
    } elseif ($stat === 3) {
        $newstat = (rand(1, 2) === 1) ? 1 : 2;
    }

    if ($newid > 2049 && $newid < 2064) {
        if ($stat === 6) {
            $item['atr_type_1'] = 6; $item['atr_type_2'] = 0; $item['atr_type_3'] = 0;
        } elseif ($stat === 5) {
            $item['atr_type_1'] = 5; $item['atr_type_2'] = 0; $item['atr_type_3'] = 0;    
        } else {
            $item['atr_type_1'] = 2; $item['atr_type_2'] = 4; $item['atr_type_3'] = 5;        
        }
    }

    if ($newid > 1049 && $newid < 1064) {
        if ($stat === 6) {
            $item['atr_type_1'] = 6; $item['atr_type_2'] = 0; $item['atr_type_3'] = 0;
        } elseif ($stat === 5) {
            $item['atr_type_1'] = 5; $item['atr_type_2'] = 0; $item['atr_type_3'] = 0;    
        } else {
            $item['atr_type_1'] = 3; $item['atr_type_2'] = 4; $item['atr_type_3'] = 5;        
        }
    }

    if ($newid > 49 && $newid < 64) {
        if ($ntype < 8) {
            if ($stat === 6) {
                $item['atr_type_1'] = 6; $item['atr_type_2'] = 0; $item['atr_type_3'] = 0;
            } elseif ($stat === 5) {
                $item['atr_type_1'] = 5; $item['atr_type_2'] = 0; $item['atr_type_3'] = 0;    
            } else {
                $item['atr_type_1'] = 1; $item['atr_type_2'] = 4; $item['atr_type_3'] = 5;        
            }
        }
    }

    if ($newid > 49 && $newid < 64) {
        if ($ntype > 7) {
            if ($stat === 6) {
                $item['atr_type_1'] = 6; $item['atr_type_2'] = 0; $item['atr_type_3'] = 0;
            } elseif ($stat === 5) {
                $item['atr_type_1'] = 5; $item['atr_type_2'] = 0; $item['atr_type_3'] = 0;    
            } else {
                $item['atr_type_1'] = $newstat; $item['atr_type_2'] = 4; $item['atr_type_3'] = 5;
            }   
        }   
    }

    if ($itemType === 1) {
        $val1 = (int)($item['atr_val_1'] ?? 0);
        $val2 = (int)($item['atr_val_2'] ?? 0);
        $val3 = (int)($item['atr_val_3'] ?? 0);

        if ($class === 1) {
            $item['atr_val_1'] = $val1 / 2; $item['atr_val_2'] = $val2 / 2; $item['atr_val_3'] = $val3 / 2;    
        } elseif ($oldClass === 1) {
            $item['atr_val_1'] = $val1 * 2; $item['atr_val_2'] = $val2 * 2; $item['atr_val_3'] = $val3 * 2;    
        }

        $class_weap_multiplier = [2, 4.2, 2.5];
        $item['dmg_min'] = round((($item['dmg_min'] ?? 0) / $class_weap_multiplier[$oldClass - 1]) * $class_weap_multiplier[$class - 1]);
        $item['dmg_max'] = round((($item['dmg_max'] ?? 0) / $class_weap_multiplier[$oldClass - 1]) * $class_weap_multiplier[$class - 1]);
    }

    return $item;
}

function getIP() { 
    // Cloudflare
    if (!empty($_SERVER['HTTP_CF_CONNECTING_IP'])) {
        return $_SERVER['HTTP_CF_CONNECTING_IP'];
    }

    $headers = [
        'HTTP_X_REAL_IP',
        'HTTP_X_FORWARDED_FOR',
        'HTTP_CLIENT_IP',
        'HTTP_X_CLIENT_IP',
        'HTTP_X_CLUSTER_CLIENT_IP',
        'REMOTE_ADDR'
    ];

    foreach ($headers as $header) {
        if (!empty($_SERVER[$header])) {
            $ip = $_SERVER[$header];
            
            if ($header === 'HTTP_X_FORWARDED_FOR') {
                $ips = explode(',', $ip);
                $ip = trim($ips[0]);
            }
            
            if (filter_var($ip, FILTER_VALIDATE_IP)) {
                return $ip;
            }
        }
    }

    return $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
}

$req = $_GET['req'];
$SSID = substr($req, 0, 32); 
$action = substr($req, 32, 3); 
$action_extra = substr($req, 35);

require_once 'dbconnect.php';
require_once 'globals.php';

$lastcount1 = 0;
$lastcount2 = 0;
$ret = array_fill(0, 511, '0');

switch ($action) {
    case $ACT_REGISTER:
        $npe = explode(";", $action_extra ?? '');
        $nick  = $npe[0] ?? '';
        $pass  = $npe[1] ?? '';
        $email = urlencode(strtolower($npe[2] ?? ''));

        if (strlen($nick) < 3 || strlen($nick) > 20) {
            $ret = [$ERR_NAME_TOO_SHORT];
            break;
        }

        if (preg_match("/[^-a-z0-9_ ]/i", $nick)) {
            $ret = [$ERR_NAME_EXISTS];
            break;
        }

        if (strlen($pass) < 4) {
            $ret = [$ERR_PASSWORD_TOO_SHORT];
            break;
        }

        if (preg_match("/[^-a-z0-9_]/i", $pass)) {
            $ret = [$ERR_NAME_EXISTS];
            break;
        }

        $cmail = $npe[2] ?? '';
        if (filter_var($cmail, FILTER_VALIDATE_EMAIL) === false) {
            $ret = [$ERR_EMAIL_WRONG];
            break;
        }

        $qry = $db->prepare("SELECT user_name, email FROM user_data WHERE user_name = :name OR email = :email");
        $qry->execute([
            ':name'  => $nick,
            ':email' => $email
        ]);

        if ($qry->rowCount() > 0) {
            $duplicate = $qry->fetch(PDO::FETCH_ASSOC);
            if (($duplicate['email'] ?? '') === $email) {
                $ret = [$ERR_EMAIL_EXISTS];
                break;
            }
            $ret = [$ERR_NAME_EXISTS];
            break;
        }

        $looksStr = $npe[8] ?? '';
        $looks    = explode("/", $looksStr);
        $class    = (int)($npe[7] ?? 1);
        $race     = (int)($npe[5] ?? 1);
        $gender   = (int)($npe[6] ?? 1);
        
        $stats = loadDefaultStats($class, $race);
        $hashedPass = md5($pass); 
        $ip = getIP();

        $ipc = $db->prepare("SELECT user_id FROM user_data WHERE last_ip = :ip");
        $ipc->execute([':ip' => $ip]);
        if ($ipc->rowCount() >= 3) {
            $ret = [$ERR_ACCOUNTS_PER_IP];
            break;
        }

        $qry = $db->prepare("SELECT * FROM game_settings WHERE setting IN ('QUEST_EXP', 'QUEST_GOLD') ORDER BY id ASC");
        $qry->execute();
        $res = $qry->fetchAll(PDO::FETCH_ASSOC);
        
        $expSetting  = $res[0]['value'] ?? 1;
        $goldSetting = $res[1]['value'] ?? 1;
        
        $tpBonus = 1;
        $goldBonus = 1;
        $currentEvent = event();
        
        if ($currentEvent == 1) $tpBonus = 1.5;
        if ($currentEvent == 3) $goldBonus = 2;
        if ($currentEvent == 5) { 
            $tpBonus = 1.5;
            $goldBonus = 2;
        }

        $basexp1 = mt_rand(200, 300);  $basexp2 = mt_rand(200, 300);  $basexp3 = mt_rand(200, 300);
        $basegold1 = mt_rand(30, 70);  $basegold2 = mt_rand(30, 70);  $basegold3 = mt_rand(30, 70);
        
        $m1 = mt_rand(900, 1100) / 1000;
        $m2 = mt_rand(900, 1100) / 1000;
        $m3 = mt_rand(900, 1100) / 1000;
        
        $l1 = rand(1, 2); $l2 = rand(1, 2); $l3 = rand(1, 2);

        $xp  = (0.5 * $expSetting * $m1 * $l1) * $tpBonus + $basexp1;
        $xp2 = (0.5 * $expSetting * $m2 * $l2) * $tpBonus + $basexp2;
        $xp3 = (0.5 * $expSetting * $m3 * $l3) * $tpBonus + $basexp3;

        $gd  = (1 * (1 / 40) * (1 / 40) * $goldSetting * $m1 * $l1) * $goldBonus + $basegold1;
        $gd2 = (1 * (1 / 40) * (1 / 40) * $goldSetting * $m2 * $l2) * $goldBonus + $basegold2;
        $gd3 = (1 * (1 / 40) * (1 / 40) * $goldSetting * $m3 * $l3) * $goldBonus + $basegold3;

        $lc  = rand(1, 21); $lc2 = rand(1, 21); $lc3 = rand(1, 21);

        $qry = $db->prepare("INSERT INTO user_data (user_name, password, email, last_ip, face1, face2, face3, face4, face5, face6, face7, face8, face9, face10, reg_date, class, race, gender, attr_str, attr_agi, attr_int, attr_wit, attr_luck, quest_gold_1, quest_gold_2, quest_gold_3, quest_exp_1, quest_exp_2, quest_exp_3, quest_location_1, quest_location_2, quest_location_3, quest_dur_1, quest_dur_2, quest_dur_3) 
            VALUES (:name, :pass, :email, :lastip, :face1, :face2, :face3, :face4, :face5, :face6, :face7, :face8, :face9, :face10, :reg_date, :class, :race, :gender, :str, :agi, :int, :wit, :luck, :qg1, :qg2, :qg3, :qe1, :qe2, :qe3, :lc1, :lc2, :lc3, :qd1, :qd2, :qd3)");

        $insertParams = [
            ':name'     => $nick,
            ':lastip'   => $ip,
            ':pass'     => $hashedPass,
            ':email'    => $email,
            ':reg_date' => time(), 
            ':class'    => $class,
            ':race'     => $race,
            ':gender'   => $gender,
            ':str'      => $stats[0] ?? 10,
            ':agi'      => $stats[1] ?? 10,
            ':int'      => $stats[2] ?? 10,
            ':wit'      => $stats[3] ?? 10,
            ':luck'     => $stats[4] ?? 10,
            ':qg1'      => $gd,  ':qg2' => $gd2, ':qg3' => $gd3,
            ':qe1'      => $xp,  ':qe2' => $xp2, ':qe3' => $xp3,
            ':lc1'      => $lc,  ':lc2' => $lc2, ':lc3' => $lc3,
            ':qd1'      => $l1,  ':qd2' => $l2,  ':qd3' => $l3
        ];

        for ($i = 1; $i <= 10; $i++) {
            $insertParams[':face' . $i] = $looks[$i - 1] ?? 1;
        }

        $qry->execute($insertParams);

        $qry = $db->prepare("SELECT user_id FROM user_data WHERE user_name = :name LIMIT 1");
        $qry->execute([':name' => $nick]);
        $res = $qry->fetchAll(PDO::FETCH_ASSOC);
        $newUserId = $res[0]['user_id'] ?? 0;

        if ($class === 1) {
            $item_id = 1; $dmg_min = 4; $dmg_max = 8;
        } elseif ($class === 2) {
