        $ret[] = $weap['atr_type_1'] ?? 0; $ret[] = $weap['atr_type_2'] ?? 0; $ret[] = $weap['atr_type_3'] ?? 0;
        $ret[] = $weap['atr_val_1'] ?? 0; $ret[] = $weap['atr_val_2'] ?? 0; $ret[] = $weap['atr_val_3'] ?? 0;
        $ret[] = $weap['gold'] ?? 0; $ret[] = ($weap['mush'] ?? 0);

