        $ret[] = $p1shield['atr_val_1'] ?? 0; $ret[] = $p1shield['atr_val_2'] ?? 0; $ret[] = $p1shield['atr_val_3'] ?? 0; $ret[] = $p1shield['gold'] ?? 0; $ret[] = $p1shield['mush'] ?? 0;
        
        $ret[] = $charOP->hasShield(); $ret[] = $opshield['item_id'] ?? 0; $ret[] = $opshield['dmg_min'] ?? 0; $ret[] = $opshield['dmg_max'] ?? 0;
        $ret[] = $opshield['atr_type_1'] ?? 0; $ret[] = $opshield['atr_type_2'] ?? 0; $ret[] = $opshield['atr_type_3'] ?? 0; $ret[] = $opshield['atr_val_1'] ?? 0; $ret[] = $opshield['atr_val_2'] ?? 0; $ret[] = $opshield['atr_val_3'] ?? 0; $ret[] = $opshield['gold'] ?? 0;
        
