            $mlogStr = str_replace(';', '#', $mlogStr);
            $sub = $win ? 6 : 7;

            $qry = $db->prepare("INSERT INTO messages (sender_id, reciver_id, time, subject, msg) VALUES (:sid, :rid, :time, :subj, :msg)");
            $qry->execute([
