                $Album->encode();

                $qry = $db->prepare("UPDATE user_data SET album_data = :adata, album = :acount WHERE user_id = :uid");
                $qry->bindParam(':adata', $Album->data);
                $qry->bindParam(':acount', $Album->count);
                $qry->bindParam(':uid', $p1['user_id']);
