            break;
        }

        $newSilver = $db_data['silver'] - $cost;
        $newStatVal = 3 + $db_data['stat'];

        $qry = $db->prepare("UPDATE user_data SET silver = :silver, {$statRowName} = :statval WHERE ssid = :ssid");
        $qry->execute([
            ':silver'  => $newSilver,
            ':statval' => $newStatVal,
            ':ssid'    => $SSID
        ]);

        $db_data = loadDefaultData();
        $ret[0] = $ACT_HERO . ($ret[0] ?? '');
        $ret[511] = ($ret[511] ?? '') . ";" . fixSpecialChars(urldecode($db_data['user_desc'] ?? '')) . ";";
        break;

    case $ACT_RANKING:
        $in = explode(';', $action_extra ?? '');
        $pos = 0;

        if (ctype_digit($in[1] ?? '')) {
            $pos = (int)str_replace(';', '', $action_extra);
        } else {
            $nick = $in[0] ?? ''; 
            $qry = $db->prepare("SELECT pos FROM (
                SELECT honor, lvl, user_name, user_id, @r:=@r+1 as pos
                FROM user_data, (SELECT @r:=0) r0
                ORDER BY honor DESC, lvl DESC, user_id DESC
            ) user_data_ordered WHERE user_name = :name LIMIT 1");
            $qry->execute([':name' => $nick]);
            $posRow = $qry->fetch(PDO::FETCH_NUM);
            $pos = (int)($posRow[0] ?? 0);
        }

        if ($pos < 8) {
            $pos = 8;
        }

        $qry = $db->prepare("SELECT Count(*) FROM user_data");
        $qry->execute();
        $playerCountRow = $qry->fetch(PDO::FETCH_NUM);
        $playerCount = (int)($playerCountRow[0] ?? 0);

        if ($pos > $playerCount && $playerCount > 8) {
            $pos = $playerCount;
        }
        if ($pos > $playerCount && $playerCount < 8) {
            $pos = 8;
        }

        $posFrom = $pos - 8;
        
        $qry = $db->prepare("SELECT *, (SELECT guilds.name FROM guilds WHERE guilds.guild_id = user_data.guild_id) AS guild FROM user_data ORDER BY honor DESC, lvl DESC, user_id DESC LIMIT :pos1, 15");
        $qry->bindParam(':pos1', $posFrom, PDO::PARAM_INT);
        $qry->execute();
        $res = $qry->fetchAll(PDO::FETCH_ASSOC);

        $ret = ["007"];
        $pos -= 7;
        $index = 0;

        foreach ($res as $row) {
            $ret[$index]     = urlencode((string)$pos);
            $ret[$index + 1] = $row['user_name'] ?? '';
            $ret[$index + 2] = $row['guild'] ?? '';
            $ret[$index + 3] = $row['lvl'] ?? 0;
            $ret[$index + 4] = $row['honor'] ?? 0;
            $ret[$index + 5] = round(time() - ((int) ($row['last_activ'] ?? 0))) <= 900 ? 1 : 0;
            
            $class = (int)($row['class'] ?? 1);
            if ($class === 2) { 
                $ret[$index + 3] = "-" . $ret[$index + 3];
            } elseif ($class === 3) { 
                $ret[$index] = "-" . $ret[$index];
            }

            $pos++;
            $index += 6;
        }
        
        $ret[0] = "007" . ($ret[0] ?? '');
        $ret[] = ";";
        break;

    case $ACT_SCREEN_PILZDEALER:
        $ret = ["0160"];
        break;

    case $ACT_SCREEN_WITCH:
        $db_data = loadDefaultData();
        $ret[0] = $RESP_SCREEN_WITCH . ($ret[0] ?? '');
        loadWitchData($db_data);
        break;      

    case $ACT_WITCH_ENCHANT:
        $qry = $db->prepare("SELECT * FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $db_data = $qry->fetch(PDO::FETCH_ASSOC) ?? [];

        $in = $action_extra;
        $cost = round(($db_data['lvl'] ?? 1) * ($db_data['lvl'] ?? 1) * 256, -2);
        $userId = (int)($db_data['user_id'] ?? 0);

        $enchants = array_fill(0, 9, 0);
        $hasItem = array_fill(0, 9, false);
        $slots = [8, 1, 3, 2, 0, 5, 4, 6, 7];

        foreach ($slots as $slotId) {
            $qry = $db->prepare("SELECT enchant FROM items WHERE owner_id = :oid AND slot = :slot LIMIT 1");
            $qry->execute([':oid' => $userId, ':slot' => $slotId]);
            $itemRow = $qry->fetch(PDO::FETCH_ASSOC);
            
            if ($itemRow) {
                $hasItem[$slotId] = true;
                $enchants[$slotId] = (int)($itemRow['enchant'] ?? 0);
            }
        }

        $qry = $db->prepare("SELECT * FROM witch WHERE id = 1 LIMIT 1");
        $qry->execute();       
        $witch = $qry->fetch(PDO::FETCH_ASSOC) ?? [];

        if (($db_data['silver'] ?? 0) >= $cost) {
            $scrollVal = (int)($witch['scroll_' . $in] ?? 0);

            $enchantMapping = [
                11  => ['slot' => 8, 'current' => $enchants[8], 'enchant' => 184549376,  'power' => 327680],
                31  => ['slot' => 1, 'current' => $enchants[1], 'enchant' => 520093696,  'power' => 65536],
                41  => ['slot' => 3, 'current' => $enchants[3], 'enchant' => 687865856,  'power' => 1966080],
                51  => ['slot' => 2, 'current' => $enchants[2], 'enchant' => 855638016,  'power' => 65536],
                61  => ['slot' => 0, 'current' => $enchants[0], 'enchant' => 1023410176, 'power' => 655360],
                71  => ['slot' => 5, 'current' => $enchants[5], 'enchant' => 1191182336, 'power' => 65536],
                81  => ['slot' => 4, 'current' => $enchants[4], 'enchant' => 1358954496, 'power' => 655360],
                91  => ['slot' => 6, 'current' => $enchants[6], 'enchant' => 1526726656, 'power' => 65536],
                101 => ['slot' => 7, 'current' => $enchants[7], 'enchant' => 1694498816, 'power' => 1310720],
            ];

            if (isset($enchantMapping[$scrollVal])) {
                $map = $enchantMapping[$scrollVal];

                if ($hasItem[$map['slot']] && $map['current'] == 0) {
                    $db_data['silver'] -= $cost;

                    $qry = $db->prepare("UPDATE user_data SET silver = :silver WHERE user_id = :id");
                    $qry->execute([':silver' => $db_data['silver'], ':id' => $userId]);

                    $qry = $db->prepare("UPDATE items SET enchant = :enchant, enchant_power = :power WHERE owner_id = :id AND slot = :slot");
                    $qry->execute([
                        ':enchant' => $map['enchant'],
                        ':power'   => $map['power'],
                        ':id'      => $userId,
                        ':slot'    => $map['slot']
                    ]);
                } else {
                    break;
                }
            }
        } else {
            $ret = [$ERR_TOO_EXPENSIVE];
            break;
        }

        $u_data = loadDefaultData();
        $ret[0] = $RESP_SCREEN_WITCH . ($ret[0] ?? '');
        loadWitchData($u_data);
        break;

    case $ACT_WITCH_DONATE:        
        $in = explode(';', $action_extra ?? '');
        $slotType = (int)($in[0] ?? 0);
        $slotIdx  = (int)($in[1] ?? 0);

        if ($slotType === 1) {
            $slotIdx -= 1;
        } elseif ($slotType === 2) {
            $slotIdx += 9;
        }

        $qry = $db->prepare("SELECT * FROM witch WHERE id = 1 LIMIT 1");
        $qry->execute();
        $witch = $qry->fetch(PDO::FETCH_ASSOC) ?? [];

        $qry = $db->prepare("SELECT * FROM items WHERE slot = :slot AND owner_id = (SELECT user_id FROM user_data WHERE ssid = :ssid LIMIT 1) LIMIT 1");
        $qry->execute([':slot' => $slotIdx, ':ssid' => $SSID]);
        $item = $qry->fetch(PDO::FETCH_ASSOC) ?? [];

        $qry = $db->prepare("SELECT * FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $user_data = $qry->fetch(PDO::FETCH_ASSOC) ?? [];

        if (($item['item_type'] ?? null) != ($witch['donation_type'] ?? null)) {
            $db_data = loadDefaultData();
            $ret[0] = $RESP_SCREEN_WITCH . ($ret[0] ?? '');
            loadWitchData($db_data);
            break;
        }

        if (($witch['item_amount'] ?? 0) >= ($witch['item_max_amount'] ?? 0)) { 
            $qry = $db->prepare("UPDATE witch SET work = 1 WHERE id = 1");
            $qry->execute(); 
            $db_data = loadDefaultData();
            $ret[0] = $RESP_SCREEN_WITCH . ($ret[0] ?? '');
            loadWitchData($db_data);
            break;  
        }

        $qry = $db->prepare("UPDATE witch SET item_amount = item_amount + 1 WHERE id = 1");
        $qry->execute();  

        $qry = $db->prepare("DELETE FROM items WHERE id = :iid");
        $qry->execute([':iid' => $item['id'] ?? 0]);

        $itemValue = ($item['gold'] ?? 0) * 2;
        $user_data['silver'] += $itemValue;

        $qry = $db->prepare("UPDATE user_data SET silver = :gold WHERE ssid = :ssid");
        $qry->execute([':ssid' => $SSID, ':gold' => $user_data['silver']]); 

        $db_data = loadDefaultData();
        $ret[0] = $RESP_SCREEN_WITCH . ($ret[0] ?? '');
        loadWitchData($db_data);
        break;

    case $ACT_SCREEN_TOWER:
        $db_data = loadDefaultData();
        $ret[0] = $RESP_TOWER_SAVE . ($ret[0] ?? ''); 
        loadDefaultCopycatData($db_data);
        break;

    case $ACT_MOVE_COPYCAT_ITEM:
        $in = explode(';', $action_extra);

        // Determine tower helper na podstawie parametru docelowego lub źródłowego
        if (in_array($in[2], [101, 102, 103])) {
            $towerHelperCode = $in[2];
        } elseif (in_array($in[0], [101, 102, 103])) {
            $towerHelperCode = $in[0];
        } else {
            $towerHelperCode = null;
        }

        if ($towerHelperCode == 101) $towerHelper = 1;
        elseif ($towerHelperCode == 102) $towerHelper = 2;
        elseif ($towerHelperCode == 103) $towerHelper = 3;
        else $towerHelper = null;

        $slot = $in[1] + 9;

        // Fetch item from inventory
        $qry = $db->prepare("
            SELECT * FROM items
            WHERE owner_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
            AND slot = :slot
        ");
        $qry->bindParam(':ssid', $SSID);
        $qry->bindParam(':slot', $slot);
        $qry->execute();
        $item = $qry->fetch(PDO::FETCH_ASSOC);

        // --- SPRAWDZENIE KIERUNKU RUCHU ---

        if (in_array($in[2], [101, 102, 103])) {
            // TRYB A: Przenoszenie z ekwipunku DO WIEŻY pomocnika
            if ($item && $item['item_type'] < 8 && 
                ($item['item_id'] < $towerHelper * 1000 - 1000 || $item['item_id'] > $towerHelper * 1000) ||
                ($item && $item['item_type'] == 2)) {
                // invalid item - do nothing
            } else if ($item) {
                $in[2] = getSlotIndex($item['item_type']);
                $item['slot'] = $in[2] + 1;

                $qry = $db->prepare("
                    SELECT * FROM tower_helper_items 
                    WHERE slot = :slot 
                    AND user_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
                    AND tower_helper = :thelper
                ");
                $qry->bindParam(':slot', $item['slot']);
                $qry->bindParam(':thelper', $towerHelper);
                $qry->bindParam(':ssid', $SSID);
                $qry->execute();
                $blockItem = $qry->fetch(PDO::FETCH_ASSOC);

                $curslot = $in[1] + 9;

                if ($qry->rowCount() < 1) {
                    // Insert new tower item
                    $qry = $db->prepare("
                        INSERT INTO tower_helper_items 
                        (user_id, tower_helper, item_type, item_id, dmg_min, dmg_max,
                        atr_type_1, atr_type_2, atr_type_3, atr_val_1, atr_val_2, atr_val_3,
                        gold, mush, slot, toilet, enchant, enchant_power, upgrade_level)
                        VALUES (
                            (SELECT user_id FROM user_data WHERE ssid = :ssid), :thelper,
                            {$item['item_type']}, {$item['item_id']}, {$item['dmg_min']}, {$item['dmg_max']},
                            {$item['atr_type_1']}, {$item['atr_type_2']}, {$item['atr_type_3']},
                            {$item['atr_val_1']}, {$item['atr_val_2']}, {$item['atr_val_3']},
                            {$item['gold']}, {$item['mush']}, {$item['slot']}, {$item['toilet']},
                            {$item['enchant']}, {$item['enchant_power']}, {$item['upgrade_level']}
                        )
                    ");
                    $qry->bindParam(':thelper', $towerHelper);
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();

                    // Delete from inventory
                    $qry = $db->prepare("
                        DELETE FROM items 
                        WHERE owner_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
                        AND slot = :curslot
                    ");
                    $qry->bindParam(':curslot', $curslot);
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();
                    
                } else {
                    // Swap: Usuń stary z EQ
                    $qry = $db->prepare("
                        DELETE FROM items 
                        WHERE owner_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
                        AND slot = :curslot
                    ");
                    $qry->bindParam(':curslot', $curslot);
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();

                    // Swap: Usuń stary z wieży
                    $qry = $db->prepare("
                        DELETE FROM tower_helper_items 
                        WHERE user_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
                        AND slot = :slot AND tower_helper = :thelper
                    ");
                    $qry->bindParam(':slot', $blockItem['slot']);
                    $qry->bindParam(':thelper', $towerHelper);
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();

                    // Swap: Wstaw nowy przedmiot do wieży
                    $qry = $db->prepare("
                        INSERT INTO tower_helper_items 
                        (user_id, tower_helper, item_type, item_id, dmg_min, dmg_max,
                        atr_type_1, atr_type_2, atr_type_3, atr_val_1, atr_val_2, atr_val_3,
                        gold, mush, slot, toilet, enchant, enchant_power, upgrade_level)
                        VALUES (
                            (SELECT user_id FROM user_data WHERE ssid = :ssid), :thelper,
                            {$item['item_type']}, {$item['item_id']}, {$item['dmg_min']}, {$item['dmg_max']},
                            {$item['atr_type_1']}, {$item['atr_type_2']}, {$item['atr_type_3']},
                            {$item['atr_val_1']}, {$item['atr_val_2']}, {$item['atr_val_3']},
                            {$item['gold']}, {$item['mush']}, {$blockItem['slot']}, {$item['toilet']},
                            {$item['enchant']}, {$item['enchant_power']}, {$item['upgrade_level']}
                        )
                    ");
                    $qry->bindParam(':thelper', $towerHelper);
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();

                    // Swap: Pobierz user_id i znajdź wolne miejsce w EQ dla starego przedmiotu z wieży
                    $qry = $db->prepare("SELECT user_id FROM user_data WHERE ssid = :ssid");
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();
                    $user_id = $qry->fetchColumn();

                    $slotInfo = findFreeSlot($user_id, $curslot);
                    $curslot = $slotInfo[1];

                    $qry = $db->prepare("
                        INSERT INTO items 
                        (item_type, item_id, dmg_min, dmg_max, atr_type_1, atr_type_2, atr_type_3,
                        atr_val_1, atr_val_2, atr_val_3, gold, mush, slot, owner_id,
                        toilet, enchant, enchant_power, upgrade_level)
                        VALUES (
                            {$blockItem['item_type']}, {$blockItem['item_id']}, {$blockItem['dmg_min']}, {$blockItem['dmg_max']},
                            {$blockItem['atr_type_1']}, {$blockItem['atr_type_2']}, {$blockItem['atr_type_3']},
                            {$blockItem['atr_val_1']}, {$blockItem['atr_val_2']}, {$blockItem['atr_val_3']},
                            {$blockItem['gold']}, {$blockItem['mush']}, :curslot,
                            (SELECT user_id FROM user_data WHERE ssid = :ssid),
                            {$item['toilet']}, {$item['enchant']}, {$item['enchant_power']}, {$item['upgrade_level']}
                        )
                    ");
                    $qry->bindParam(':curslot', $curslot);
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();
                }
            }

        } elseif (in_array($in[0], [101, 102, 103])) {
            // TRYB B: Ściąganie przedmiotu Z WIEŻY do ekwipunku
            $slot2 = $in[1];

            $qry = $db->prepare("
                SELECT * FROM tower_helper_items 
                WHERE user_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
                AND slot = :slot AND tower_helper = :thelper
            ");
            $qry->bindParam(':slot', $slot2);
            $qry->bindParam(':thelper', $towerHelper);
            $qry->bindParam(':ssid', $SSID);
            $qry->execute();
            $item2 = $qry->fetch(PDO::FETCH_ASSOC);

            if ($item2) {
                $item2['slot'] = $in[3] + 9;

                $qry = $db->prepare("
                    SELECT * FROM items 
                    WHERE slot = :slot 
                    AND owner_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
                ");
                $qry->bindParam(':slot', $item2['slot']);
                $qry->bindParam(':ssid', $SSID);
                $qry->execute();

                if ($qry->rowCount() < 1) {
                    $qry = $db->prepare("
                        INSERT INTO items 
                        (item_type, item_id, dmg_min, dmg_max, atr_type_1, atr_type_2, atr_type_3,
                        atr_val_1, atr_val_2, atr_val_3, gold, mush, slot, owner_id,
                        toilet, enchant, enchant_power, upgrade_level)
                        VALUES (
                            {$item2['item_type']}, {$item2['item_id']}, {$item2['dmg_min']}, {$item2['dmg_max']},
                            {$item2['atr_type_1']}, {$item2['atr_type_2']}, {$item2['atr_type_3']},
                            {$item2['atr_val_1']}, {$item2['atr_val_2']}, {$item2['atr_val_3']},
                            {$item2['gold']}, {$item2['mush']}, {$item2['slot']},
                            (SELECT user_id FROM user_data WHERE ssid = :ssid),
                            {$item2['toilet']}, {$item2['enchant']}, {$item2['enchant_power']}, {$item2['upgrade_level']}
                        )
                    ");
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();

                    $qry = $db->prepare("
                        DELETE FROM tower_helper_items 
                        WHERE user_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
                        AND slot = :slot AND tower_helper = :thelper
                    ");
                    $qry->bindParam(':slot', $in[1]);
                    $qry->bindParam(':thelper', $towerHelper);
                    $qry->bindParam(':ssid', $SSID);
                    $qry->execute();
                }
            }

        } else {
            // TRYB C: Zamiana/porządkowanie miejsc wyłącznie wewnątrz ekwipunku
            $tarslot = $in[3] + 9;
            $curslot = isset($item['slot']) ? $item['slot'] : $slot;

            $qry = $db->prepare("
                UPDATE items SET slot = :newslot 
                WHERE owner_id = (SELECT user_id FROM user_data WHERE ssid = :ssid)
                AND slot = :oldslot
            ");
            $qry->bindParam(':newslot', $tarslot);
            $qry->bindParam(':oldslot', $curslot);
            $qry->bindParam(':ssid', $SSID);
            $qry->execute();

            if ($item && isset($item['id'])) {
                $qry = $db->prepare("
                    UPDATE items SET slot = :tarslot 
                    WHERE id = :itemid
                ");
                $qry->bindParam(':tarslot', $tarslot);
                $qry->bindParam(':itemid', $item['id'], PDO::PARAM_INT);
                $qry->execute();
            }
        }

        $db_data = loadDefaultData();
        $ret[0] = $RESP_MOVE_TOWER_ITEM . $ret[0];
        loadDefaultCopycatData($db_data);
        break;

    case $ACT_COPYCAT_BOOST:
        $db_data = loadDefaultData();
        $ret[0] = $RESP_TOWER_SAVE . ($ret[0] ?? '');
        
        $input = explode(';', $action_extra ?? '');
        $copycat_id = (int)($input[0] ?? 1);
        
        $lvl  = explode(":", $db_data['copycat_lvl'] ?? '');
        $str  = explode(":", $db_data['copycat_str'] ?? '');
        $dex  = explode(":", $db_data['copycat_dex'] ?? '');
        $int  = explode(":", $db_data['copycat_int'] ?? '');
        $wit  = explode(":", $db_data['copycat_wit'] ?? '');
        $luck = explode(":", $db_data['copycat_luck'] ?? '');
        
        $baseValue = 73516;        
        $multipler = 2053;      
        $baseLvl   = 150;     
        
        $idx = $copycat_id - 1;
        $diff = ($lvl[$idx] ?? $baseLvl) - $baseLvl;                        
        $cost = ($baseValue + $multipler * $diff) * 100;

        if (($db_data['silver'] ?? 0) < $cost) {
            $ret = [$ERR_TOO_EXPENSIVE];
            break;
        }
        if (($db_data['lvl'] ?? 1) <= ($lvl[$idx] ?? 0)) {
            break;
        }

        $lvl[$idx] = (int)($lvl[$idx] ?? 0) + 1;
        
        if ($copycat_id === 1) {
            $str[$idx]  = (int)($str[$idx] ?? 0) + 12;
            $dex[$idx]  = (int)($dex[$idx] ?? 0) + 5; 
            $int[$idx]  = (int)($int[$idx] ?? 0) + 5;
            $wit[$idx]  = (int)($wit[$idx] ?? 0) + 10;
            $luck[$idx] = (int)($luck[$idx] ?? 0) + 10; 
        } elseif ($copycat_id === 2) {
            $str[$idx]  = (int)($str[$idx] ?? 0) + 5;
            $dex[$idx]  = (int)($dex[$idx] ?? 0) + 5; 
            $int[$idx]  = (int)($int[$idx] ?? 0) + 12;
            $wit[$idx]  = (int)($wit[$idx] ?? 0) + 10;
            $luck[$idx] = (int)($luck[$idx] ?? 0) + 10; 
        } elseif ($copycat_id === 3) {
            $str[$idx]  = (int)($str[$idx] ?? 0) + 5;
            $dex[$idx]  = (int)($dex[$idx] ?? 0) + 12; 
            $int[$idx]  = (int)($int[$idx] ?? 0) + 5;
            $wit[$idx]  = (int)($wit[$idx] ?? 0) + 10;
            $luck[$idx] = (int)($luck[$idx] ?? 0) + 10; 
        }

        $copycat_lvl  = implode(":", $lvl);
        $copycat_str  = implode(":", $str);
        $copycat_dex  = implode(":", $dex);
        $copycat_int  = implode(":", $int);
        $copycat_wit  = implode(":", $wit);
        $copycat_luck = implode(":", $luck);
        $db_data['silver'] -= $cost;

        $qry = $db->prepare("UPDATE user_data SET silver = :silver, copycat_lvl = :lvl, copycat_str = :str, copycat_dex = :dex, copycat_int = :int, copycat_wit = :wit, copycat_luck = :luck WHERE ssid = :ssid");
        $qry->execute([
            ':silver' => $db_data['silver'],
            ':lvl'    => $copycat_lvl,
            ':str'    => $copycat_str,
            ':dex'    => $copycat_dex,
            ':int'    => $copycat_int,
            ':wit'    => $copycat_wit,
            ':luck'   => $copycat_luck,
            ':ssid'   => $SSID
        ]);

        $db_data = loadDefaultData();
        $ret[0] = $RESP_TOWER_SAVE . ($ret[0] ?? '');
        loadDefaultCopycatData($db_data);
        break; 

    case $ACT_TOWER_TRY:
        $db_data = loadDefaultData();
        $slotInfo = findFreeSlot($db_data['user_id']);
        
        if (($slotInfo[0] ?? false) == false) {
            $ret = [$ERR_INVENTORY_FULL];
            break;
        }

        $time = time(); 
        if ($time < ($db_data['dungeon_time'] ?? 0)) {
            if (($db_data['mushroom'] ?? 0) <= 0) {
                break;
            }
            $db_data['mushroom'] -= 1;
            $time = $db_data['dungeon_time'];
        } else {
            $time += 3600;
        }

        $stage = $db_data['tower_level'] ?? 1;
        $OP = getTowerMonster($stage, $db_data);
        $OP1 = getTowerMonster($stage, $db_data);
        $round = 0;
        
        $lvl  = explode(":", $db_data['copycat_lvl'] ?? '');
        $str  = explode(":", $db_data['copycat_str'] ?? '');
        $dex  = explode(":", $db_data['copycat_dex'] ?? '');
        $int  = explode(":", $db_data['copycat_int'] ?? '');
        $wit  = explode(":", $db_data['copycat_wit'] ?? '');
        $luck = explode(":", $db_data['copycat_luck'] ?? '');
        
        $c_data = ['user_id' => $db_data['user_id']];
        $t_ret = ['321'];

        while ($round < 4 && $OP->getHP() > 0) {
            if ($round == 3) {
                $p = new Char($db_data);
            } else {
                $c_data['id']        = 391 + $round;
                $c_data['class']     = $round + 1;
                $c_data['lvl']       = $lvl[$round] ?? 1;
                $c_data['attr_str']  = $str[$round] ?? 10;
                $c_data['attr_agi']  = $dex[$round] ?? 10;
                $c_data['attr_int']  = $int[$round] ?? 10;
                $c_data['attr_luck'] = $luck[$round] ?? 10;
                $c_data['attr_wit']  = $wit[$round] ?? 10;
                $p = new Copycat($c_data);
            }

            $t_ret[count($t_ret) - 1] .= $p->getHP();
            array_push($t_ret, $p->getStr(), $p->getDex(), $p->getInt(), $p->getWit(), $p->getLuck());
            array_push($t_ret, $OP1->getHP(), $OP->getStr(), $OP->getDex(), $OP->getInt(), $OP->getWit(), $OP->getLuck() . ";"); 

            $handicap = ($OP->getHP() != $OP1->getHP()) ? $OP->getHP() : '-1';

            $sim = SF_Calc::calculateWin($p, $OP, 'mobattack');
            $t_ret[count($t_ret) - 1] .= $sim[0][0] ?? 0;
            array_push($t_ret, $sim[0][1] ?? 0, $sim[0][2] ?? 0);
            
            $simCount = count($sim);
            for ($i = 1; $i < $simCount; $i++) {
                array_push($t_ret, $sim[$i][0] ?? 0, $sim[$i][1] ?? 0, $sim[$i][2] ?? 0);
            }

            if ($round == 3) {
                array_push($t_ret, ";" . ($db_data['user_name'] ?? ''), $p->getLvl(), $db_data['race'] ?? 1, $db_data['gender'] ?? 1, $db_data['class'] ?? 1);
                for ($i = 1; $i <= 9; $i++) {
                    $t_ret[] = $db_data['face' . $i] ?? 0;
                }
            } else {
                $skin = 391 + $round;
                array_push($t_ret, ";" . ($db_data['user_name'] ?? ''), $p->getLvl(), '0', '0', ($round + 1), '-' . $skin);
                for ($i = 1; $i <= 8; $i++) {
                    $t_ret[] = 0;
                }
            }

            array_push($t_ret, "0", "0", $OP->getLvl(), "0", "0", "1", "-" . $OP->getId(), "0", "0", "0", "0", "0", "0", "0", "0", "0;" . $p->hasWeapon());
            
            $weap = $p->getWeapon();
            array_push($t_ret, $weap['item_id'] ?? 0, $weap['dmg_min'] ?? 0, $weap['dmg_max'] ?? 0, $weap['atr_type_1'] ?? 0, $weap['atr_type_2'] ?? 0, $weap['atr_type_3'] ?? 0, $weap['atr_val_1'] ?? 0, $weap['atr_val_2'] ?? 0, $weap['atr_val_3'] ?? 0, $weap['gold'] ?? 0, $weap['mush'] ?? 0);
            
            $weap = $OP->getWeapon();
            array_push($t_ret, $OP->hasWeapon(), $weap['item_id'] ?? 0, $weap['dmg_min'] ?? 0, $weap['dmg_max'] ?? 0, $weap['atr_type_1'] ?? 0, $weap['atr_type_2'] ?? 0, $weap['atr_type_3'] ?? 0, $weap['atr_val_1'] ?? 0, $weap['atr_val_2'] ?? 0, $weap['atr_val_3'] ?? 0, $weap['gold'] ?? 0, ($weap['mush'] ?? 0) . ";" . $p->hasShield());
            
            $sh = $p->getShield();
            array_push($t_ret, $sh['item_id'] ?? 0, $sh['dmg_min'] ?? 0, $sh['dmg_max'] ?? 0, $sh['atr_type_1'] ?? 0, $sh['atr_type_2'] ?? 0, $sh['atr_type_3'] ?? 0, $sh['atr_val_1'] ?? 0, $sh['atr_val_2'] ?? 0, $sh['atr_val_3'] ?? 0, $sh['gold'] ?? 0, $sh['mush'] ?? 0);
            
            $sh = $OP->getShield();
            array_push($t_ret, $OP->hasShield(), $sh['item_id'] ?? 0, $sh['dmg_min'] ?? 0, $sh['dmg_max'] ?? 0, $sh['atr_type_1'] ?? 0, $sh['atr_type_2'] ?? 0, $sh['atr_type_3'] ?? 0, $sh['atr_val_1'] ?? 0, $sh['atr_val_2'] ?? 0, $sh['atr_val_3'] ?? 0, $sh['gold'] ?? 0);

            if ($round == 0) {
                $c1 = 2; $c2 = 3; $c3 = $db_data['user_name'] ?? '';
            } elseif ($round == 1) {
                $c1 = 3; $c2 = $db_data['user_name'] ?? ''; $c3 = '';
            } elseif ($round == 2) {
                $c1 = $db_data['user_name'] ?? ''; $c2 = ''; $c3 = '';
            } else {
                $c1 = ''; $c2 = ''; $c3 = '';
            }

            $t_ret[] = ($sh['mush'] ?? 0) . ';2;0;0;0;-1;;5;6§-1/' . $c1 . '/' . $c2 . '/' . $c3 . '///' . $handicap . '/////§';
            $round++;
        }

        $win = $OP->getHP() <= 0;
        if ($win) {
            $stage++;
            $db_data['silver'] += round($OP->getGoldTower() * 100, -2);
            $lvl = $db_data['lvl'] ?? 1;
            $statvalue = $OP->getLvl();
            if ($statvalue > $lvl) {
                $statvalue = $lvl;
            }
            $class = rand(1, 3);
            while ($class == ($db_data['class'] ?? 1)) {
                $class = rand(1, 3);
            }
            $shop = rand(0, 2) - 1;
            if ($shop < 0) {
                $shop = 0;
            }
            
            $item = genItem($statvalue, $class, $shop, 'tower');
            $item['slot'] = $slotInfo[1];

            $qry = $db->prepare('INSERT INTO items (item_type, item_id, dmg_min, dmg_max, atr_type_1, atr_type_2, atr_type_3, atr_val_1, atr_val_2, atr_val_3, gold, mush, slot, owner_id, toilet) 
                VALUES (:item_type, :item_id, :dmg_min, :dmg_max, :atr_type_1, :atr_type_2, :atr_type_3, :atr_val_1, :atr_val_2, :atr_val_3, :gold, :mush, :slot, :owner_id, :toilet)');
            $qry->execute([
                ':item_type'  => $item['item_type'],  ':item_id'   => $item['item_id'],
                ':dmg_min'    => $item['dmg_min'],    ':dmg_max'   => $item['dmg_max'],
                ':atr_type_1' => $item['atr_type_1'], ':atr_type_2'=> $item['atr_type_2'], ':atr_type_3' => $item['atr_type_3'],
                ':atr_val_1'  => $item['atr_val_1'],  ':atr_val_2' => $item['atr_val_2'],  ':atr_val_3'  => $item['atr_val_3'],
                ':gold'       => 0,                   ':mush'      => $item['mush'],
                ':slot'       => $item['slot'],       ':owner_id'  => $db_data['user_id'], ':toilet' => 1
            ]);
            
            $itmslot = $item['slot'] - 10;
        } else {
            $itmslot = '-1';
        }

        $qry = $db->prepare("UPDATE user_data SET lvl = :lvl, silver = :silver, mushroom = :shroom, dungeon_time = :time, tower_level = :tower_level WHERE ssid = :ssid");
        $qry->execute([
            ':lvl'         => $db_data['lvl'],
            ':silver'      => $db_data['silver'],
            ':shroom'      => $db_data['mushroom'],
            ':time'        => $time,
            ':tower_level' => $stage,
            ':ssid'        => $SSID
        ]);

        $t_ret[count($t_ret) - 1] .= ";" . $OP->getGoldTower() . ";" . $itmslot . ";" . '0' . ";0;-1§";
        loadDefaultData();
        
        $t_ret[count($t_ret) - 1] .= $ret[0] ?? '';
        $ret[$SF_DUNGEON_ENDTIME] = $time;
        
        $retCount = count($ret);
        for ($i = 1; $i < $retCount; $i++) {
            $t_ret[] = $ret[$i];
        }
        
        exit(implode("/", $t_ret));
        break;

    case $ACT_SCREEN_TOILET:
        $time = time();
        $db_data = loadDefaultData();

        if ($time > (int)($db_data['toilet_time'] ?? 0)) {
            $db_data['toilet_time'] = strtotime('tomorrow');
            $db_data['toilet_full'] = 0;
            
            $qry = $db->prepare("UPDATE user_data SET toilet_time = :time, toilet_full = :toilet_full WHERE ssid = :ssid");
            $qry->execute([
                ':time'        => $db_data['toilet_time'],
                ':toilet_full' => $db_data['toilet_full'],
                ':ssid'        => $SSID
            ]);
        }
        
        if (($db_data['toilet'] ?? 0) == 0) {
            $ret[0] = $RESP_TOILET_LOCKED . ($ret[0] ?? '');
            break;
        } elseif ($db_data['toilet'] == 1) {
            $ret[0] = $ACT_SCREEN_TOILET . ($ret[0] ?? '');
        } else {
            break;
        }
        
        $ret[] = (";" . $db_data['toilet_full'] . ";" . $db_data['aura'] . ";" . $db_data['fill_level'] . ";" . $db_data['fill_level_next']);
        break;

    case $ACT_TOILET_FLUSH:
        $db_data = loadDefaultData();
        if (($db_data['fill_level'] ?? 0) < ($db_data['fill_level_next'] ?? 1)) {
            $ret[0] = $ERR_TOILET_EMPTY . ($ret[0] ?? '');
            $ret[] = (";" . $db_data['toilet_full'] . ";" . $db_data['aura'] . ";" . $db_data['fill_level'] . ";" . $db_data['fill_level_next']);
            break;
        }
        
        $lvl   = $db_data['lvl'] ?? 1;
        $class = $db_data['class'] ?? 1;
        $shop  = rand(0, 1);
        $item  = genItem($lvl, $class, $shop, 'toilet');
        
        $slotInfo = findFreeSlot($db_data['user_id']);
        if (($slotInfo[0] ?? false) == true) {
            $item['slot'] = $slotInfo[1];
            $slot = $slotInfo[1] - 10;
        } else {
            $ret[0] = $ERR_NO_SLOT_FOR_FLUSHING . ($ret[0] ?? '');
            $ret[] = (";" . $db_data['toilet_full'] . ";" . $db_data['aura'] . ";" . $db_data['fill_level'] . ";" . $db_data['fill_level_next']);
            break;
        }           

        $qry = $db->prepare('INSERT INTO items (item_type, item_id, dmg_min, dmg_max, atr_type_1, atr_type_2, atr_type_3, atr_val_1, atr_val_2, atr_val_3, gold, mush, slot, owner_id) 
            VALUES (:item_type, :item_id, :dmg_min, :dmg_max, :atr_type_1, :atr_type_2, :atr_type_3, :atr_val_1, :atr_val_2, :atr_val_3, :gold, :mush, :slot, :owner_id)');
        $qry->execute([
            ':item_type'  => $item['item_type'],  ':item_id'   => $item['item_id'],
            ':dmg_min'    => $item['dmg_min'],    ':dmg_max'   => $item['dmg_max'],
            ':atr_type_1' => $item['atr_type_1'], ':atr_type_2'=> $item['atr_type_2'], ':atr_type_3' => $item['atr_type_3'],
            ':atr_val_1'  => $item['atr_val_1'],  ':atr_val_2' => $item['atr_val_2'],  ':atr_val_3'  => $item['atr_val_3'],
            ':gold'       => $item['gold'],       ':mush'      => $item['mush'],
            ':slot'       => $item['slot'],       ':owner_id'  => $db_data['user_id']
        ]);

        $db_data['fill_level'] = 0;
        $db_data['aura'] += 1;
        $db_data['fill_level_next'] = getFillLevel($db_data['aura']);

        $qry = $db->prepare("UPDATE user_data SET fill_level = :fill_level, fill_level_next = :fill_level_next, aura = :aura, toilet_full = :toilet_full WHERE ssid = :ssid");
        $qry->execute([
            ':fill_level'      => $db_data['fill_level'],
            ':fill_level_next' => $db_data['fill_level_next'],
            ':aura'            => $db_data['aura'],
            ':toilet_full'     => $db_data['toilet_full'],
            ':ssid'            => $SSID
        ]);

        $db_data = loadDefaultData();
        $ret[0] = $RESP_TOILET_FLUSHED . ($ret[0] ?? '');
        $ret[] = (";" . $db_data['toilet_full'] . ";" . $db_data['aura'] . ";" . $db_data['fill_level'] . ";" . $db_data['fill_level_next'] . ";" . $slot);
        break;

    case $ACT_GUILD_RANKING:
        $input = explode(';', $action_extra ?? '');
        $guildname = $input[0] ?? '';
        $guildid   = (int)($input[1] ?? 0);
        $pos       = (int)($input[2] ?? 0);

        if ($guildname !== "") {
            $qry = $db->prepare("SELECT pos FROM (SELECT honor, dung, guild_id, name, @r:=@r+1 as pos FROM guilds, (SELECT @r:=0) r0 ORDER BY honor DESC, dung DESC, guild_id DESC) user_data_ordered WHERE name = :name LIMIT 1");
            $qry->execute([':name' => $guildname]);
            $posRow = $qry->fetch(PDO::FETCH_NUM);
            $pos = (int)($posRow[0] ?? 1);
        } elseif ($guildid !== 0) {
            $qry = $db->prepare("SELECT pos FROM (SELECT honor, dung, guild_id, name, @r:=@r+1 as pos FROM guilds, (SELECT @r:=0) r0 ORDER BY honor DESC, dung DESC, guild_id DESC) user_data_ordered WHERE guild_id = :gid LIMIT 1");
            $qry->execute([':gid' => $guildid]);
            $posRow = $qry->fetch(PDO::FETCH_NUM);
            $pos = (int)($posRow[0] ?? 1);
        } elseif ($pos === '' || $pos === 0) {
            $pos = 1;
        }

        if ($pos < 8) {
            $pos = 8;
        }

        $qry = $db->prepare("SELECT Count(*) FROM guilds");
        $qry->execute();
        $guildsCountRow = $qry->fetch(PDO::FETCH_NUM);
        $guildsCount = (int)($guildsCountRow[0] ?? 0);

        if ($pos >= $guildsCount && $guildsCount > 8) {
            $pos = $guildsCount - 7;
        }
        if ($pos > $guildsCount && $guildsCount < 8) {
            $pos = 8;
        }

        $posFrom = $pos - 8;
        $qry = $db->prepare("SELECT name, honor, guild_id, 
            (SELECT user_data.user_name FROM user_data WHERE user_data.user_id = leader_id LIMIT 1) AS leader, 
            (SELECT Count(user_data.guild_id) FROM user_data WHERE user_data.guild_id = guilds.guild_id) AS members,
            (SELECT Count(*) FROM guild_attacks WHERE guild_attacks.target_id = guilds.guild_id) AS warstatus
            FROM guilds ORDER BY honor DESC, dung DESC, guild_id DESC LIMIT :pos, 15");
        $qry->bindParam(':pos', $posFrom, PDO::PARAM_INT);
        $qry->execute();
        $res = $qry->fetchAll(PDO::FETCH_ASSOC);

        $ret = ["170"];
        $pos -= 7;
        
        foreach ($res as $i => $row) {
            $a = $i * 5;
            $ret[$a]     = urlencode((string)$pos);
            $ret[$a + 1] = $row['leader'] ?? '';
            $ret[$a + 2] = $row['name'] ?? '';
            
            $war = ''; 
            if ((int)($row['warstatus'] ?? 0) > 0) {
                $war = '-';
            }
            $ret[$a + 3] = $war . ($row['members'] ?? 0);
            $ret[$a + 4] = $row['honor'] ?? 0;
            $pos++;
        }
        
        $ret[0] = "170" . ($ret[0] ?? '');
        break;

    case $ACT_TAVERN_ENTER:
        $time = time();
        $db_data = loadDefaultData();   
        
        if ($time > (int)($db_data['quest_reroll_time'] ?? 0)) {
            $db_data['quest_reroll_time'] = strtotime('tomorrow');
            $db_data['thirst'] = 6000;
            $db_data['beers'] = 0;
            
            $ret[$SF_THIRST] = 6000;
            $ret[$SF_BEERS] = 0;
            
            $qry = $db->prepare("UPDATE user_data SET quest_reroll_time = :time, thirst = :thirst, beers = :beer WHERE ssid = :ssid");
            $qry->execute([
                ':time'   => $db_data['quest_reroll_time'],
                ':thirst' => $db_data['thirst'],
                ':beer'   => $db_data['beers'],
                ':ssid'   => $SSID
            ]);
        }   

        if (($db_data['status'] ?? 0) == 1) {
            $ret = ["012" . getGoldForWork($db_data['lvl'] ?? 1) . ";1"];
            break;
        }

        if (($db_data['status'] ?? 0) == 2) {
            if ($time > (int)($db_data['status_end'] ?? 0)) {
                finishQuest($db_data);
                break;
            }
        }

        $ret[0] = $RESP_QUEST_SKIP_ALLOWED . ($ret[0] ?? '');
        if (($db_data['lvl'] ?? 1) < 50 && event() == 2) {
            $ret[] = ";" . 0 . ";0";
        } else {
            $ret[] = ";" . event() . ";0";  
        }
        break;

    case $ACT_START_QUEST:
        $in = explode(';', $action_extra ?? '');
        $db_data = loadDefaultData();
        $time = time();
        
        $mount = ($time < ($db_data['mount_dur'] ?? 0)) ? mountMultiplier($db_data['mount'] ?? 0) : 1;
        
        $qry = $db->prepare("SELECT enchant FROM items WHERE owner_id = :oid AND slot = 3 LIMIT 1");
        $qry->execute([':oid' => $db_data['user_id']]);
        $res = $qry->fetch(PDO::FETCH_ASSOC);
        $enchant = $res['enchant'] ?? 0;

        $questKey = 'quest_dur_' . ($in[0] ?? 1);
        if ($enchant == 687865856) {      
            $dur = ((int)($db_data[$questKey] ?? 1) * 300 * $mount) - 30;
        } else {
            $dur = ((int)($db_data[$questKey] ?? 1) * 300 * $mount);
        }   
        
        $end = $time + $dur;
        if (($db_data['status'] ?? 0) != 0) {
            break;
        }
        if (($db_data['thirst'] ?? 0) < $dur) {
            $ret = [$ERR_NO_ENDURANCE];
            break;
        }

        $qry = $db->prepare("UPDATE user_data SET status = 2, status_extra = :qpick, status_end = :end WHERE ssid = :ssid");
        $qry->execute([
            ':qpick' => $in[0] ?? 1,
            ':end'   => $end,
            ':ssid'  => $SSID
        ]);

        $db_data = loadDefaultData();
        $ret[0] = $RESP_QUEST_SKIP_ALLOWED_START . ($ret[0] ?? '');
        $ret[$SF_STATUS] = 2;
        $ret[$SF_CHOSEN_QUEST] = $in[0] ?? 1;
        $ret[$SF_ACT_ENDTIME] = $end;
        break;

    case $ACT_QUEST_CANCEL:
        $db_data = loadDefaultData();
        $qry = $db->prepare("UPDATE user_data SET status = '0', status_end = '0' WHERE ssid = :ssid");
        $qry->execute([':ssid' => $SSID]);
        
        $ret[$SF_STATUS] = 0;
        $ret[0] = $RESP_QUEST_STOP . ($ret[0] ?? '');
        break;

    case $ACT_QUEST_SKIP:
        $db_data = loadDefaultData();
        if (($db_data['mushroom'] ?? 0) <= 1) {
            $ret = [$ERR_NO_MUSH_BAR];
            break;
        }
        $db_data['mushroom'] -= 1;
        
        $qry = $db->prepare("UPDATE user_data SET mushroom = :shroom, status_end = 0 WHERE ssid = :ssid");
        $qry->execute([
            ':shroom' => $db_data['mushroom'],
            ':ssid'   => $SSID
        ]);
        
        finishQuest($db_data);
        $ret[$SF_STATUS] = 0;
        break;

    case $ACT_WORK_ENTER:
        $qry = $db->prepare("SELECT * FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $db_data = $qry->fetch(PDO::FETCH_ASSOC) ?? [];
        
        $time = time();
        $sph = getGoldForWork($db_data['lvl'] ?? 1);

        if ((int)($db_data['status'] ?? 0) == 1 && (int)($db_data['status_end'] ?? 0) < $time) {
            $gain = ($sph * (int)($db_data['status_extra'] ?? 0));
            $db_data['silver'] += $gain;
            $db_data['medal_employment'] += (int)($db_data['status_extra'] ?? 0);

            $qry = $db->prepare("UPDATE user_data SET status = 0, silver = :silver, medal_employment = :medal_employment WHERE ssid = :ssid");
            $qry->execute([
                ':silver'           => $db_data['silver'],
                ':medal_employment' => $db_data['medal_employment'],
                ':ssid'             => $SSID
            ]);
            
            loadDefaultData();
            $ret[0] = "103" . ($ret[0] ?? '');
            $ret[511] = ($ret[511] ?? '') . ";" . $gain;
        } else {
            $ret = ["012" . $sph . ";0"];
        }
        break;

    case $ACT_WORK:
        $in = (int)$action_extra;
        $db_data = loadDefaultData();
        $time = time();

        if ((int)($db_data['status'] ?? 0) == 1 && (int)($db_data['status_end'] ?? 0) < $time) { 
            break;
        }
        
        $end = $time + (3600 * $in);
        $qry = $db->prepare("UPDATE user_data SET status = 1, status_end = :end, status_extra = :hours WHERE ssid = :ssid");
        $qry->execute([
            ':end'   => $end,
            ':hours' => $in,
            ':ssid'  => $SSID
        ]);
        
        $ret[0] = "104" . ($ret[0] ?? '');
        $ret[$SF_STATUS] = 1;
        $ret[$SF_ACT_ENDTIME] = $end;
        $ret[46] = $in;
        break;

    case $ACT_WORK_CANCEL:
        $qry = $db->prepare("UPDATE user_data SET status = 0 WHERE ssid = :ssid");
        $qry->execute([':ssid' => $SSID]);
        
        loadDefaultData();
        $ret[0] = "105" . ($ret[0] ?? '');
        break;

    case $ACT_BARN:
        $qry = $db->prepare("SELECT lvl FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $user = $qry->fetch(PDO::FETCH_ASSOC);
        $uLvl = (int)($user['lvl'] ?? 1);
        
        $ret = ['015' . (23 + $uLvl) * $uLvl * $uLvl];
        break;

    case $ACT_BUY_MOUNT:
        $mount = (int)$action_extra;
        $cost   = mountCost($mount);
        $silver = $cost['silver'] ?? 0;
        $shroom = $cost['shroom'] ?? 0;

        $qry = $db->prepare("SELECT mount, mount_dur, silver, mushroom FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $res = $qry->fetch(PDO::FETCH_ASSOC) ?? [];
        
        $time = time();
        $cur_mount = ($time < (int)($res['mount_dur'] ?? 0)) ? (int)($res['mount'] ?? 0) : 0;

        if ($cur_mount > $mount) {
            break;
        }
        if ($silver > ($res['silver'] ?? 0)) {
            $ret = [$ERR_TOO_EXPENSIVE];
            break;
        }
        if ($shroom > ($res['mushroom'] ?? 0)) {
            $ret = [$ERR_NO_MUSH_MQ];
            break;
        }

        $silver = $res['silver'] - $silver;
        $shroom = $res['mushroom'] - $shroom;
        $mount_dur = (int)($res['mount_dur'] ?? 0);

        if ($mount_dur <= $time || $mount != $cur_mount) {
            $mount_dur = $time + 1209600;
        } else {
            $mount_dur += 1209600; 
        }

        if ($mount >= 4) {
            $qry = $db->prepare("SELECT lvl FROM user_data WHERE ssid = :ssid LIMIT 1");
            $qry->execute([':ssid' => $SSID]);
            $user = $qry->fetch(PDO::FETCH_ASSOC);
            $uLvl = (int)($user['lvl'] ?? 1);   
            $silver += ((23 + $uLvl) * $uLvl * $uLvl); 
        }   

        $qry = $db->prepare("UPDATE user_data SET mount = :mount, mount_dur = :mount_dur, silver = :silver, mushroom = :shroom WHERE ssid = :ssid");
        $qry->execute([
            ':mount'     => $mount,
            ':mount_dur' => $mount_dur,
            ':silver'    => $silver,
            ':shroom'    => $shroom,
            ':ssid'      => $SSID
        ]);

        $db_data = loadDefaultData();
        $ret[0] = $ACT_HERO . ($ret[0] ?? '');
        $ret[511] = ($ret[511] ?? '') . ";" . fixSpecialChars(urldecode($db_data['user_desc'] ?? '')) . ";";
        break;

    case $ACT_ENTER_SHOP_SHAKES:
        $db_data = loadDefaultData();
        enterShop($SHOP_SHAKES, $db_data);
        
        $ret[0] = $ACT_ENTER_SHOP_SHAKES . ($ret[0] ?? '');
        $ret[]  = (($db_data['lvl'] ?? 1) >= 50) ? ";" . event() : ";";
        break;

    case $ACT_ENTER_SHOP_FIDGET:
        $db_data = loadDefaultData();
        enterShop($SHOP_FIDGET, $db_data);
        
        $ret[0] = $ACT_ENTER_SHOP_FIDGET . ($ret[0] ?? '');
        $ret[]  = (($db_data['lvl'] ?? 1) >= 50) ? ";" . event() : ";";
        break;

    case $ACT_DRINK_BEER:
        $db_data = loadDefaultData();

        $qry = $db->prepare("SELECT * FROM game_settings WHERE setting IN ('UNLIMITED_BEERS') ORDER BY id ASC");
        $qry->execute();
        $res = $qry->fetchAll(PDO::FETCH_ASSOC);
        $enabled = $res[0]['value'] ?? 0;

        $c = ($enabled == 1) ? 0 : 1;

        if (($db_data['beers'] ?? 0) >= 11) {
            $ret = [$ERR_BEER];
            break;
        }
        if (($db_data['mushroom'] ?? 0) <= 0) {
            $ret = [$ERR_NO_MUSH_BAR];
            break;
        }
        if (($db_data['thirst'] ?? 0) > 4800) {
            break;
        }

        $db_data['thirst'] += 1200;
        $db_data['beers']  += $c;
        
        $qry2 = $db->prepare("SELECT value FROM server_config WHERE name = 'EVENT_OCTOBERFEST' LIMIT 1");
        $qry2->execute();
        $res = $qry2->fetchAll(PDO::FETCH_ASSOC);
        $event = $res[0]['value'] ?? 0;    
        
        if ($event != 1) {
            $db_data['mushroom'] -= 1;
        }

        $qry = $db->prepare("UPDATE user_data SET thirst = :thirst, beers = :beers, mushroom = :shroom WHERE ssid = :ssid");
        $qry->execute([
