            ':beers'  => $db_data['beers'],
            ':shroom' => $db_data['mushroom'],
            ':ssid'   => $SSID
        ]);

        $ret[0] = "010" . ($ret[0] ?? '');
        $ret[$SF_THIRST] = $db_data['thirst'];
        $ret[$SF_BEERS]  = $db_data['beers'];
        $ret[$SF_MUSH]   = $db_data['mushroom'];
        break;

    case $ACT_ENTER_GUILD:
        $qry = $db->prepare("SELECT * FROM guilds WHERE guild_id = (SELECT user_data.guild_id FROM user_data WHERE user_data.ssid = :ssid) LIMIT 1");
