                    $qry->execute([':gid' => $a_data['guild_id']]);
                    $targetn = $qry->fetch(PDO::FETCH_NUM);
                    
                    if (($resp[2] ?? false) == true) {
                        $success = 'yes';
                        $msg1 = '#r+#' . ($targetn[0] ?? 0) . '#' . ($resp[3] ?? 0);
                    } else {
                        $success = 'no';
                        $msg1 = '#r-#' . (($targetn[0] ?? 0) + 1) . '#' . ($resp[3] ?? 0);
                    }
                } else {
                    $qry = $db->prepare("SELECT name FROM guilds WHERE guild_id = :gid LIMIT 1");
                    $qry->execute([':gid' => $a_data['guild_id']]);
                    $attackern = $qry->fetch(PDO::FETCH_NUM);
                    
                    $qry = $db->prepare("SELECT name FROM guilds WHERE guild_id = :gid LIMIT 1");
                    $qry->execute([':gid' => $a_data['target_id']]);
                    $targetn = $qry->fetch(PDO::FETCH_NUM);
                    
                    if (($resp[2] ?? false) == true) {
                        $success = 'yes';
                        $msg1 = '#a+#' . ($targetn[0] ?? '') . '#' . ($resp[3] ?? 0);
                        $msg2 = '#d-#' . ($attackern[0] ?? '') . '#' . ($resp[3] ?? 0);
                    } else {
                        $success = 'no';
                        $msg1 = '#a-#' . ($targetn[0] ?? '') . '#' . ($resp[3] ?? 0);
