                $qry->execute([':gid' => $a_data['guild_id'], ':msg' => $msg1]);
                $qry->execute([':gid' => $a_data['target_id'], ':msg' => $msg2]);
                
                $qry = $db->prepare("UPDATE user_data SET gattack_last = :aid WHERE ssid = :ssid");
