                $qry = $db->prepare("UPDATE user_data SET guild_attack = '0' WHERE guild_id = (SELECT guild_id FROM guild_attacks WHERE attack_id = :aid LIMIT 1)");
                $qry->execute([':aid' => $a_data['attack_id']]);
                
                $qry = $db->prepare("UPDATE user_data SET guild_defend = '0' WHERE guild_id = (SELECT target_id FROM guild_attacks WHERE attack_id = :aid LIMIT 1)");
                $qry->execute([':aid' => $a_data['attack_id']]);
                
                $qry = $db->prepare("SELECT honor FROM guilds WHERE guild_id = (SELECT target_id FROM guild_attacks WHERE attack_id = :aid LIMIT 1) LIMIT 1");
                $qry->execute([':aid' => $a_data['attack_id']]);
                $g_honor_row = $qry->fetch(PDO::FETCH_NUM);
                $g_honor = ($g_honor_row[0] ?? 0) - (int)($resp[3] ?? 0);
                
                $qry = $db->prepare("UPDATE guilds SET honor = :ghonor WHERE guild_id = (SELECT target_id FROM guild_attacks WHERE attack_id = :aid LIMIT 1)");
                $qry->execute([':aid' => $a_data['attack_id'], ':ghonor' => $g_honor]);
                
                $qry = $db->prepare("SELECT honor FROM guilds WHERE guild_id = (SELECT guild_id FROM guild_attacks WHERE attack_id = :aid LIMIT 1) LIMIT 1");
                $qry->execute([':aid' => $a_data['attack_id']]);
                $g_honor_row = $qry->fetch(PDO::FETCH_NUM);
                $g_honor = ($g_honor_row[0] ?? 0) + (int)($resp[3] ?? 0);
                
                $qry = $db->prepare("UPDATE guilds SET honor = :ghonor WHERE guild_id = (SELECT guild_id FROM guild_attacks WHERE attack_id = :aid LIMIT 1)");
                $qry->execute([':aid' => $a_data['attack_id'], ':ghonor' => $g_honor]);
                
                $ret = (($g_data['guild_id'] ?? 0) == $a_data['target_id']) ? ['178' . $fight2] : ['178' . $fight];
                
