        }
        
        $qry = $db->prepare("SELECT * FROM guild_attacks_archive WHERE guild_id = (SELECT user_data.guild_id FROM user_data WHERE user_data.ssid = :ssid1) OR target_id = (SELECT user_data.guild_id FROM user_data WHERE user_data.ssid = :ssid2) ORDER BY attack_id DESC LIMIT 1");
        $qry->execute([':ssid1' => $SSID, ':ssid2' => $SSID]);
