                $qry->execute([':ssid' => $SSID, ':aid' => $a_data['attack_id']]);
                
                $ret = (($g_data['guild_id'] ?? 0) == $a_data['target_id']) ? ['178' . ($a_data['fight_data_reverse'] ?? '')] : ['178' . ($a_data['fight_data'] ?? '')];
                break;
            }
        }
        
        $qry = $db->prepare("SELECT * FROM user_data WHERE guild_id = (SELECT user_data.guild_id FROM user_data WHERE ssid = :ssid) ORDER BY guild_rank ASC, lvl DESC");
