        $m_data = $qry->fetchAll(PDO::FETCH_ASSOC);
        
        $qry = $db->prepare("SELECT user_data.*, guild_invites.guild_id FROM user_data INNER JOIN guild_invites ON user_data.user_id = guild_invites.user_id WHERE guild_invites.guild_id = :gid ORDER BY user_data.lvl DESC");
        $qry->execute([':gid' => $g_data['guild_id'] ?? 0]);
        $im_data = $qry->fetchAll(PDO::FETCH_ASSOC);
        
        $qry = $db->prepare("SELECT pos FROM (SELECT honor, dung, guild_id, name, @r:=@r+1 as pos FROM guilds, (SELECT @r:=0) r0 ORDER BY honor DESC, dung DESC, guild_id DESC) user_data_ordered WHERE guild_id = :gid LIMIT 1");
        $qry->execute([':gid' => $g_data['guild_id'] ?? 0]);
        $posRow = $qry->fetch(PDO::FETCH_NUM);
