            $monsters[] = getDungMonster($i, $db_data['dungeon_' . $i] ?? 0, $db_data);
        }
        
        $ret[] = ";" . ($monsters[0]->getId() ?? 0);
        for ($i = 1; $i < 13; $i++) {
            $ret[] = $monsters[$i]->getId() ?? 0;
        }
        break;

    case $ACT_MAINQUEST:
        $dung = (int)$action_extra;
        $db_data = loadDefaultData();
        if (($db_data['dungeon_' . $dung] ?? 0) >= 12) {
            break;
        }

        if (($db_data['dungeon_' . $dung] ?? 0) < 2) {
            $ret = [$ERR_SESSION_ID_EXPIRED];
            break;
        }
        
        $slotInfo = findFreeSlot($db_data['user_id']);
        if (($slotInfo[0] ?? false) == false) {
            $ret = [$ERR_INVENTORY_FULL];
            break;
