            $time = $db_data['dungeon_time'];
        } else {
            $time += 3600;
        }
        
        $stage = (int)($db_data['dungeon_' . $dung] ?? 1);
        $OP = getDungMonster($dung, $stage, $db_data);
        $p = new Char($db_data);
        $t_ret = [];
        
        $t_ret[] = "122" . $p->getHP();
        array_push($t_ret, $p->getStr(), $p->getDex(), $p->getInt(), $p->getWit(), $p->getLuck());
