                    $qry = $db->prepare("INSERT INTO guild_chat (sender_id, reciver_id, guild_id, msg, time, type) VALUES ((SELECT user_data.user_id FROM user_data WHERE user_data.ssid = :ssid LIMIT 1), '0', :gid, :msg, :time, '0')");
                    $qry->execute([
