        $sh = $p->getShield();
        array_push($t_ret, $sh['item_id'] ?? 0, $sh['dmg_min'] ?? 0, $sh['dmg_max'] ?? 0, $sh['atr_type_1'] ?? 0, $sh['atr_type_2'] ?? 0, $sh['atr_type_3'] ?? 0, $sh['atr_val_1'] ?? 0, $sh['atr_val_2'] ?? 0, $sh['atr_val_3'] ?? 0, $sh['gold'] ?? 0, $sh['mush'] ?? 0);
        
