            $sr = $srRow[0] ?? 0;
            
            $msgs[] = '#sr#' . $sr;
            $count++;
            
            if ($last_seen_msg == '0') {
                $qry = $db->prepare("UPDATE user_data SET gchat_last = '1' WHERE ssid = :ssid");
                $qry->execute([':ssid' => $SSID]);
            }
        }

        $ret = createMessageFormat($msgs, $count);
        break;

    case $ACT_POST_SEND_GUILD:
        $db_data = loadDefaultData();
        if (($db_data['lvl'] ?? 1) < 10) {
            $ret = [$ERR_MSG_LEVEL_TOO_LOW];
        }
        if (($db_data['email_validated'] ?? '0') != '1') {
            $ret = [$ERR_MSG_NOT_VALIDATED];
        }

        $qry = $db->prepare("SELECT user_id FROM user_data WHERE guild_id = (SELECT guild_id FROM user_data WHERE ssid = :ssid1 LIMIT 1) AND user_id != (SELECT user_id FROM user_data WHERE ssid = :ssid2 LIMIT 1)");
        $qry->execute([':ssid1' => $SSID, ':ssid2' => $SSID]);
        $g_members = $qry->fetchAll(PDO::FETCH_NUM);

        $action_extra_split = explode(';', $action_extra ?? '');
        $time = time();
        $sub  = urlencode($action_extra_split[1] ?? '');
        $msg  = urlencode($action_extra_split[2] ?? '');

        if (strlen($sub) < 3) {
            $ret = [$ERR_SUBJECT_TOO_SHORT];
            break;
        }

        $qryCount = $db->prepare("SELECT COUNT(*) FROM messages WHERE reciver_id = :uid");
        $qryIns   = $db->prepare("INSERT INTO messages (sender_id, reciver_id, time, subject, msg) VALUES ((SELECT user_id FROM user_data WHERE ssid = :ssid LIMIT 1), :to, :time, :sub, :msg)");

        foreach ($g_members as $member) {
            $targetUid = $member[0];
            $qryCount->execute([':uid' => $targetUid]);
            $countRow = $qryCount->fetch(PDO::FETCH_NUM);
            
            if (($countRow[0] ?? 0) < 100) {
                $qryIns->execute([
                    ':ssid' => $SSID,
                    ':to'   => $targetUid,
                    ':time' => $time,
                    ':sub'  => $sub,
                    ':msg'  => $msg
                ]);
            }
        }

        $ret = [202];
        break;

    case $ACT_GUILD_INVITE:
        $in = explode(';', $action_extra ?? '');
        
        $qry = $db->prepare("SELECT guild_id, guild_rank, user_id FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $action_user = $qry->fetch(PDO::FETCH_ASSOC);

        if (!$action_user || $action_user['guild_rank'] > 2 || $action_user['guild_rank'] < 1) {
            $ret = ["no leader"];
            break;
        }

        $qry = $db->prepare("SELECT fortress, name FROM guilds WHERE guild_id = :gid LIMIT 1");
        $qry->execute([':gid' => $action_user['guild_id']]);
        $guild = $qry->fetch(PDO::FETCH_ASSOC);

        $qry = $db->prepare("SELECT COUNT(*) FROM user_data WHERE guild_id = :gid");
        $qry->execute([':gid' => $action_user['guild_id']]);
        $guild_count_row = $qry->fetch(PDO::FETCH_NUM);
        $guild_count = $guild_count_row[0] ?? 0;

        if (($guild['fortress'] ?? 0) <= $guild_count) {
            $ret = ["fort"];
            break;
        }

        $qry = $db->prepare("SELECT user_id FROM user_data WHERE user_name = :name LIMIT 1");
        $qry->execute([':name' => $in[2] ?? '']);
        $invited_user = $qry->fetch(PDO::FETCH_ASSOC);

        if (!$invited_user) {
            $ret = [$ERR_GUILD_PLAYER_NOT_FOUND];
            break;
        }

        $qry = $db->prepare("INSERT INTO guild_invites (guild_id, user_id) VALUES (:gid, :uid)");
        $qry->execute([
            ':gid' => $action_user['guild_id'],
            ':uid' => $invited_user['user_id']
        ]);

        $qry = $db->prepare("INSERT INTO messages (sender_id, reciver_id, time, subject, msg) VALUES (:auid, :iuid, :time, 5, :msg)");
        $qry->execute([
            ':auid' => $action_user['user_id'],
