    case $ACT_GAMBLE:
        $bet = explode(';', $action_extra ?? '');
        
        $qry = $db->prepare("SELECT *, 
            (SELECT Count(*) FROM messages WHERE messages.read = 0 AND messages.reciver_id = user_data.user_id) AS c, 
            (SELECT Count(*) + 1 FROM user_data WHERE user_data.honor > (SELECT honor FROM user_data WHERE ssid = :ssid LIMIT 1)) AS rank2 
            FROM user_data WHERE ssid = :ssid2 LIMIT 1");
        $qry->execute([':ssid' => $SSID, ':ssid2' => $SSID]);
        $db_data = $qry->fetch(PDO::FETCH_ASSOC);

        if (!$db_data) {
            break;
        }

        $qry = $db->prepare("SELECT pos FROM (
            SELECT honor, lvl, user_name, ssid, user_id, @r:=@r+1 as pos
            FROM user_data, (SELECT @r:=0) r0
            ORDER BY honor DESC, lvl DESC, user_id DESC
        ) user_data_ordered WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $posRow = $qry->fetch(PDO::FETCH_NUM);
        $db_data['rank'] = $posRow[0] ?? 1;

        $betGold  = (int)($bet[0] ?? 0);
        $betMushs = (int)($bet[1] ?? 0);

        if ($betGold > ($db_data['silver'] ?? 0) || $betMushs > ($db_data['mushroom'] ?? 0) || $betGold < 0 || $betMushs < 0) {
            break;
        }

        $qry = $db->prepare("SELECT value FROM game_settings WHERE setting = 'GAMBLER' LIMIT 1");
        $qry->execute();
        $res = $qry->fetch(PDO::FETCH_ASSOC);
        $ccc = (int)($res['value'] ?? 50);

        $r = mt_rand(0, 100);
        if ($r < $ccc) {
            $db_data['silver']   += $betGold;
            $db_data['mushroom'] += $betMushs;
        } else {
            $db_data['silver']   -= $betGold;
            $db_data['mushroom'] -= $betMushs;
        }

        $qry = $db->prepare("UPDATE user_data SET silver = :silver, mushroom = :shroom WHERE ssid = :ssid");
        $qry->execute([
            ':silver' => $db_data['silver'],
            ':shroom' => $db_data['mushroom'],
            ':ssid'   => $SSID
        ]);

        loadDefaultData($db_data);
        $ret[0] = (($r < $ccc) ? "168" : "169") . ($ret[0] ?? '');
        break;

    case $ACT_GUILD_SET_OFFICER:
        $in = explode(';', $action_extra ?? '');
        $targetName = $in[2] ?? '';

        $qry = $db->prepare("SELECT user_id, guild_id FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $lid = $qry->fetch(PDO::FETCH_ASSOC);

