        if ($lid['user_id'] != $leader_id) {
            $ret = ["Error"];
            break;
        }

        $qry = $db->prepare("SELECT guild_rank FROM user_data WHERE user_name = :name LIMIT 1");
        $qry->execute([':name' => $targetName]);
        $rankRow = $qry->fetch(PDO::FETCH_ASSOC);
        $currentRank = (string)($rankRow['guild_rank'] ?? '3');

        $newRank = ($currentRank === '2' || $currentRank === '1') ? '2' : '2'; 
        if ($currentRank === '2') {
            $newRank = '3';
        }

        $qry = $db->prepare("UPDATE user_data SET guild_rank = :rank WHERE user_name = :name");
        if (!$qry->execute([':name' => $targetName, ':rank' => $newRank])) {
