        $qry->execute([':ssid' => $SSID, ':name' => $targetName]);
        $db_data = $qry->fetchAll(PDO::FETCH_ASSOC);

        if (count($db_data) !== 2 || ($db_data[0]['guild_id'] ?? 0) != ($db_data[1]['guild_id'] ?? 1) || ($db_data[0]['guild_rank'] ?? 0) != 1) {
            break;
        }

        $qry = $db->prepare("UPDATE user_data SET guild_rank = 1 WHERE user_id = :uid");
        $qry->execute([':uid' => $db_data[1]['user_id']]);

        $qry = $db->prepare("UPDATE user_data SET guild_rank = 2 WHERE user_id = :uid");
        $qry->execute([':uid' => $db_data[0]['user_id']]);

        $qry = $db->prepare("UPDATE guilds SET leader_id = :lid WHERE guild_id = :gid");
        if (!$qry->execute([':gid' => $db_data[0]['guild_id'], ':lid' => $db_data[1]['user_id']])) {
