    case $ACT_GUILD_EXPEL:
        $in = explode(';', $action_extra ?? '');
        $in_target = $in[2] ?? '';
        $ret = ["156"];

        $qry = $db->prepare("SELECT user_id, guild_id, guild_rank FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $actor_data = $qry->fetch(PDO::FETCH_ASSOC);

        if (!$actor_data) {
            break;
        }

        $qry = $db->prepare("SELECT user_id, guild_id, guild_rank FROM user_data WHERE user_name = :name LIMIT 1");
        $qry->execute([':name' => $in_target]);
        $target_data = $qry->fetch(PDO::FETCH_ASSOC);

        if (!$target_data) {
            break;
        }

        if ($target_data['guild_id'] == $actor_data['guild_id']) {
            if ($target_data['user_id'] == $actor_data['user_id']) {
                if ($target_data['guild_rank'] == 1) {
                    $qry = $db->prepare("SELECT user_id FROM user_data WHERE guild_id = :gid ORDER BY guild_rank ASC, lvl DESC");
                    $qry->execute([':gid' => $actor_data['guild_id']]);
                    $guild_members = $qry->fetchAll(PDO::FETCH_ASSOC);                
                    
                    if (count($guild_members) === 1) {
                        $qry = $db->prepare("DELETE FROM guilds WHERE guild_id = :gid");
                        $qry->execute([':gid' => $actor_data['guild_id']]);
                        
                        $qry = $db->prepare("UPDATE user_data SET guild_id = 0, guild_rank = 0 WHERE user_id = :uid");
                        $qry->execute([':uid' => $actor_data['user_id']]);
                        break;
                    }          
                    
                    $nextLeaderId = $guild_members[0]['user_id'];
                    $qry = $db->prepare("UPDATE user_data SET guild_rank = 1 WHERE user_id = :uid");
                    $qry->execute([':uid' => $nextLeaderId]);
                    
                    $qry = $db->prepare("UPDATE guilds SET leader_id = :lid WHERE guild_id = :gid");
                    $qry->execute([':gid' => $actor_data['guild_id'], ':lid' => $nextLeaderId]);
                }
                
                $qry = $db->prepare("UPDATE user_data SET guild_id = 0, guild_rank = 0 WHERE user_id = :uid");
                $qry->execute([':uid' => $actor_data['user_id']]);
                break;
            }

            if ($target_data['guild_rank'] <= $actor_data['guild_rank'] || $actor_data['guild_rank'] == 3 || $actor_data['guild_rank'] == 0) {
                break; 
            }
            
            $qry = $db->prepare("UPDATE user_data SET guild_id = 0, guild_rank = 0 WHERE user_id = :uid");
            $qry->execute([':uid' => $target_data['user_id']]);
        } elseif ($actor_data['guild_rank'] == 1 || $actor_data['guild_rank'] == 2) {
            $qry = $db->prepare("DELETE FROM guild_invites WHERE guild_id = :gid AND user_id = :uid");
            $qry->execute([':gid' => $actor_data['guild_id'], ':uid' => $target_data['user_id']]);
        }
        break;

    case $ACT_GUILD_JOIN:
