        $targetGid = $in[1] ?? 0;

        $qry = $db->prepare("DELETE FROM guild_invites WHERE user_id = (SELECT user_data.user_id FROM user_data WHERE user_data.ssid = :ssid LIMIT 1) AND guild_id = :gid");
        $qry->execute([':gid' => $targetGid, ':ssid' => $SSID]);
        
        if ($qry->rowCount() == 0) {
            $ret[0] = 1;
            break;
        }

        $qry = $db->prepare("UPDATE user_data SET guild_id = :gid, guild_rank = 3 WHERE ssid = :ssid");
        if ($qry->execute([':gid' => $targetGid, ':ssid' => $SSID]) && $qry->rowCount() == 1) {
            $ret = ["158"];
        }
