    case $ACT_GUILD_DONATE:
        $in = explode(';', $action_extra ?? '');
        $donation = ['silver' => 0, 'mushroom' => 0];
        
        $timeR = date("H:i");
        $donationType = (int)($in[0] ?? 1);
        $donationAmount = (int)($in[1] ?? 0);

        if ($donationType === 1) {
            $donation['silver'] = $donationAmount;
            $time = "#dg#" . $timeR;
            $msg = "#" . $donationAmount;
        } else {
            $donation['mushroom'] = $donationAmount;
            $time = "#dm#" . $timeR;
            $msg = "#" . $donationAmount;
        }

        $qry = $db->prepare("SELECT value FROM game_settings WHERE setting = 'GUILD_S_MINLEVEL' LIMIT 1");
        $qry->execute();
        $res = $qry->fetch(PDO::FETCH_ASSOC);
        $minlevel = (int)($res['value'] ?? 15);

        $qry = $db->prepare("SELECT user_data.lvl AS level, user_data.silver AS silver, user_data.mushroom AS mushroom, user_data.guild_id, guilds.silver AS gsilver, guilds.mushroom AS gmushroom FROM user_data LEFT JOIN guilds ON user_data.guild_id = guilds.guild_id WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $db_data = $qry->fetch(PDO::FETCH_ASSOC);

        if (!$db_data || $donation['silver'] < 0 || $donation['mushroom'] < 0) {
            $ret = [$ERR_GUILD_DONATE_NEG];
            break;
        }
        if (($db_data['silver'] ?? 0) < $donation['silver']) {
            $ret = [$ERR_TOO_EXPENSIVE];
            break;
        }
        if (($db_data['level'] ?? 1) < $minlevel) {
            $ret = [$ERR_MSG_LEVEL_TOO_LOW];
            break;
        }
        if (($db_data['mushroom'] ?? 0) < $donation['mushroom']) {
            $ret = [$ERR_GUILD_LACK_MUSH];
            break;
        }

        if ($minlevel <= $db_data['level']) {
            $db_data['silver']   -= $donation['silver'];
            $db_data['mushroom'] -= $donation['mushroom'];
            $db_data['gsilver']  += $donation['silver'];
            $db_data['gmushroom']+= $donation['mushroom'];

            $qry = $db->prepare("UPDATE user_data SET silver = :silver, mushroom = :shroom, g_silverspent = g_silverspent + :dsilver, g_mushroomspent = g_mushroomspent + :dmush WHERE ssid = :ssid");
            $qry->execute([
                ':ssid'    => $SSID,
                ':silver'  => $db_data['silver'],
                ':shroom'  => $db_data['mushroom'],
                ':dsilver' => $donation['silver'],
                ':dmush'   => $donation['mushroom']
            ]);

            $qry = $db->prepare("UPDATE guilds SET silver = :silver, mushroom = :shroom WHERE guild_id = :gid");
            $qry->execute([
                ':gid'    => $db_data['guild_id'],
                ':silver' => $db_data['gsilver'],
                ':shroom' => $db_data['gmushroom']
            ]);

            $qry = $db->prepare("INSERT INTO guild_chat (sender_id, reciver_id, guild_id, msg, time, type) VALUES ((SELECT user_data.user_id FROM user_data WHERE user_data.ssid = :ssid LIMIT 1), '0', :gid, :msg, :time, '0')");
            $qry->execute([
                ':ssid' => $SSID,
                ':gid'  => $db_data['guild_id'],
                ':msg'  => $msg,
                ':time' => $time
            ]);
        }

        loadDefaultData();
        $ret[0] = $RESP_GUILD_DONATE_SUCCESS . ($ret[0] ?? '');
        break;

    case $ACT_GUILD_JOIN_ATTACK:
        $qry = $db->prepare("SELECT Count(*) AS count FROM guild_attacks WHERE guild_id = (SELECT guild_id FROM user_data WHERE ssid = :ssid LIMIT 1)");
        $qry->execute([':ssid' => $SSID]);
