    case $ACT_GUILD_COMMENCE_ATTACK:
        $db_data = loadDefaultData();
        $guildId = (int)($db_data['guild_id'] ?? 0);

        $qry = $db->prepare("SELECT guild_id FROM guild_attacks WHERE guild_id = :gid LIMIT 1");
        $qry->execute([':gid' => $guildId]);
        
        if ($qry->rowCount() > 0) {
            $ret = [$ERR_GUILD_ATTACK_STATUS];
            break;
        }

        if ($action_extra === '-1') {
            $qry = $db->prepare("SELECT * FROM guilds WHERE guild_id = :gid LIMIT 1");
            $qry->execute([':gid' => $guildId]);
            $g_data = $qry->fetch(PDO::FETCH_ASSOC);

            if (!$g_data) {
                break;
            }

            $cost = getRaidCost($g_data['dung'] ?? 0) * 100;
            if ($cost > ($g_data['silver'] ?? 0)) {
                $ret = [$ERR_GUILD_TOO_EXPENSIVE];
                break;
            }

            $g_data['silver'] -= $cost;
            $qry = $db->prepare("UPDATE guilds SET silver = :silver WHERE guild_id = :gid");
            $qry->execute([':silver' => $g_data['silver'], ':gid' => $guildId]);

            $time = time() + 3600;

            $qry = $db->prepare("SELECT user_id FROM user_data WHERE ssid = :ssid LIMIT 1");
            $qry->execute([':ssid' => $SSID]);
            $initiater = $qry->fetch(PDO::FETCH_ASSOC);
            $initiaterId = (int)($initiater['user_id'] ?? 0);

            $target_id = 1000000;
            $qry = $db->prepare("INSERT INTO guild_attacks (guild_id, target_id, initiater_id, attack_time) VALUES (:guild_id, :target_id, :initiater_id, :attack_time)");
            $qry->execute([
                ':guild_id'     => $guildId,
                ':target_id'    => $target_id,
                ':initiater_id' => $initiaterId,
                ':attack_time'  => $time
            ]);

            $db_data['guild_attack'] = 1;
            $qry = $db->prepare("UPDATE user_data SET guild_attack = '1' WHERE ssid = :ssid");
            $qry->execute([':ssid' => $SSID]);

            $ret[0] = $RESP_GUILD_COMMENCE_ATTACK_OK . ($ret[0] ?? '');
            break;
        }

        $qry = $db->prepare("SELECT guild_id FROM guilds WHERE name = :name LIMIT 1");
        $qry->execute([':name' => $action_extra]);
        $target_gid_row = $qry->fetch(PDO::FETCH_ASSOC);
        $targetGid = (int)($target_gid_row['guild_id'] ?? 0);

        if ($targetGid === 0) {
            break;
        }

        $qry = $db->prepare("SELECT fortress FROM guilds WHERE guild_id = :gid LIMIT 1");
        $qry->execute([':gid' => $targetGid]);
        $fortressRow = $qry->fetch(PDO::FETCH_ASSOC);
        $fortress = (int)($fortressRow['fortress'] ?? 1);

        $cost = getGuildWarCost($fortress) * 100;

        $qry = $db->prepare("SELECT silver FROM guilds WHERE guild_id = :gid LIMIT 1");
        $qry->execute([':gid' => $guildId]);
        $g_silver_row = $qry->fetch(PDO::FETCH_NUM);
        $g_silver = (int)($g_silver_row[0] ?? 0);

        if ($cost > $g_silver) {
            $ret = [$ERR_GUILD_TOO_EXPENSIVE];
            break;
        }

        $g_silver -= $cost;
        $qry = $db->prepare("UPDATE guilds SET silver = :silver WHERE guild_id = :gid");
        $qry->execute([':silver' => $g_silver, ':gid' => $guildId]);

