            ':target_id'    => $targetGid,
            ':initiater_id' => $initiaterId,
            ':attack_time'  => $time
        ]);

        $db_data['guild_attack'] = 1;
        $qry = $db->prepare("UPDATE user_data SET guild_attack = '1' WHERE ssid = :ssid");
        $qry->execute([':ssid' => $SSID]);

        $ret[0] = $RESP_GUILD_COMMENCE_ATTACK_OK . ($ret[0] ?? '');
