    case $ACT_REWATCH_BATTLE:
        $qry = $db->prepare("SELECT guild_id FROM user_data WHERE ssid = :ssid LIMIT 1");
        $qry->execute([':ssid' => $SSID]);
        $gidRow = $qry->fetch(PDO::FETCH_NUM);
        $gid = $gidRow[0] ?? 0;

        $qry = $db->prepare("SELECT * FROM guild_attacks_archive WHERE guild_id = :gid OR target_id = :gid ORDER BY attack_id DESC LIMIT 1");
        $qry->execute([':gid' => $gid]);
        $g_battle = $qry->fetch(PDO::FETCH_ASSOC);

        if (!$g_battle) {
            $ret = ['+E105'];
            break;
        }

        $fightData = (($g_battle['guild_id'] ?? 0) == $gid) ? ($g_battle['fight_data'] ?? '') : ($g_battle['fight_data_reverse'] ?? '');
        $ret = ['178' . $fightData];
        break;

    case $ACT_PORTAL_FIGHT:
        $db_data = loadDefaultData();
        if (strtotime('today') <= ($db_data['guild_portal'] ?? 0)) {
            break;
        }
        if (($db_data['lvl'] ?? 1) < 99) {
            break;
        }

        $qry = $db->prepare("SELECT * FROM guilds WHERE guild_id = (SELECT guild_id FROM user_data WHERE ssid = :ssid LIMIT 1) LIMIT 1");
