            $qry = $db->prepare("SELECT email FROM user_data WHERE user_name = :username LIMIT 1");
            $qry->execute([':username' => $username]);
            $udata = $qry->fetch(PDO::FETCH_ASSOC);

            if (($udata['email'] ?? '') !== urlencode(strtolower($emailInput))) {
                $ret = [$ERR_EMAIL_WRONG];
                break;
            }

            $generatePW = function(int $length = 8) {
                $dummy = array_merge(range('0', '9'), range('a', 'z'), range('A', 'Z'));
                for ($i = 1; $i <= (count($dummy) * 2); $i++) {
                    $swap = mt_rand(0, count($dummy) - 1);
                    $tmp = $dummy[$swap];
                    $dummy[$swap] = $dummy[0];
                    $dummy[0] = $tmp;
                }
                return substr(implode('', $dummy), 0, $length);
            };

            $password = $generatePW();

            $qry2 = $db->prepare("UPDATE user_data SET password = :password WHERE user_name = :username LIMIT 1");
            $qry2->execute([
                ':password' => md5($password),
                ':username' => $username
            ]);

