            $subject = "Vaše heslo - SkyLam";
            $message = "Dobrý deň " . $username . ",\n\nDíky za požiadavku na resetovánie hesla. Boli vám vygenerované tieto nové údaje:\n\nMeno: " . $username . "\nHeslo: " . $password . "\n\nTím projektu Alesia";
            
            mail($emailInput, $subject, $message, $head1);
