        $confirm = $in[3] ?? '';

        if ((int)($db_data['mushroom'] ?? 0) < 10) {
            $ret = [$ERR_GUILD_LACK_MUSH];
            break;
        }

        if (md5($password) != ($db_data['password'] ?? '')) {
            $ret = [$ERR_WRONG_PASSWORD];
            break;
        }

        if (strlen($new) < 3 || strlen($new) > 20) {
            $ret = [$ERR_NAME_TOO_SHORT];
            break;
        }

        if (preg_match("/[^-a-z0-9_ ]/i", $new)) {
            $ret = [$ERR_NAME_REJECTED];
            break;
        }

        if (strtolower($new) !== strtolower($confirm)) {
            $ret = [$ERR_NAME_REJECTED];
            break;
        }

        if ($old !== ($db_data['user_name'] ?? '')) {
            $ret = [$ERR_NAME_REJECTED];
            break;
        }
        
        if (strtolower($old) === strtolower($new)) {
            $ret = [$ERR_NAME_REJECTED];
            break;
        }

        $qry = $db->prepare("SELECT user_name FROM user_data WHERE user_name = :name");
        $qry->execute([
            ':name'  => $new
        ]);

        if ($qry->rowCount() > 0) {
            $duplicate = $qry->fetch(PDO::FETCH_ASSOC);
            if (($duplicate['user_name'] ?? '') === $new) {
                $ret = [$ERR_NAME_EXISTS];
                break;
            }
            $ret = [$ERR_NAME_EXISTS];
            break;
        }

        $qry = $db->prepare("UPDATE user_data SET user_name = :newname, mushroom = mushroom - 10 WHERE ssid = :ssid");
        $qry->execute([
            ':newname' => $new,
            ':ssid'    => $SSID
        ]);

        $db_data = loadDefaultData();          
        $ret[0] = $RESP_CHANGE_NAME_OK . ($ret[0] ?? '');
        $ret[14] = $db_data['mushroom'] ?? 0;
        break;

    default:
        $ret = ["0"];
        break;
}

echo join("/", $ret);
$db = NULL;